	@Test
	public void lowHealthTintKeepsFiftyVisibleAndSeparatesTenFromOne()
	{
		double atThreshold = ProceduralRenderer.lowHealthTintResponse(
			healthSeverity(75, 75),
			50,
			0.65d);
		double atFifty = ProceduralRenderer.lowHealthTintResponse(
			healthSeverity(50, 75),
			50,
			0.65d);
		double atTen = ProceduralRenderer.lowHealthTintResponse(
			healthSeverity(10, 75),
			50,
			0.65d);
		double atOne = ProceduralRenderer.lowHealthTintResponse(
			healthSeverity(1, 75),
			50,
			0.65d);

		assertEquals("Threshold tint", 0.5d * 0.14d * Math.sqrt(0.65d), atThreshold, DELTA);
		assertTrue("50% tint: " + atFifty, atFifty > 0.17d && atFifty < 0.19d);
		assertTrue("10% tint: " + atTen, atTen > 0.29d && atTen < 0.31d);
		assertTrue("1% tint: " + atOne, atOne > 0.39d && atOne < 0.41d);
		assertTrue(atTen > atFifty + 0.10d);
		assertTrue(atOne > atTen + 0.09d);

		assertEquals(0, ProceduralRenderer.lowHealthTintResponse(1, 0, 1), DELTA);
		assertEquals(0, ProceduralRenderer.lowHealthTintResponse(1, 100, 0), DELTA);
		assertEquals(0.5d,
			ProceduralRenderer.lowHealthTintResponse(1, 50, 1), DELTA);
		assertEquals(1.0d,
			ProceduralRenderer.lowHealthTintResponse(1, 100, 1), DELTA);
		assertEquals(
			ProceduralRenderer.lowHealthTintResponse(1, 100, 0.25d) * 0.5d,
			ProceduralRenderer.lowHealthTintResponse(1, 50, 0.25d),
			DELTA);

		double previous = 0;
		for (int step = 0; step <= 100; step++)
		{
			double current = ProceduralRenderer.lowHealthTintResponse(
				step / 100.0d,
				50,
				0.65d);
			assertTrue("Tint decreased at severity " + step, current + DELTA >= previous);
			previous = current;
		}
	}

	@Test
	public void severityResponseSeparatesMildAndCriticalStates()
	{
		assertEquals(0, ProceduralRenderer.severityResponse(-1, 65), DELTA);
		assertEquals(1, ProceduralRenderer.severityResponse(2, 65), DELTA);
		assertEquals(0.20d, ProceduralRenderer.severityResponse(0.20d, 0), DELTA);
		assertEquals(0.20d, ProceduralRenderer.severityResponse(0.20d, 100), DELTA);
		assertTrue(ProceduralRenderer.severityResponse(0.80d, 100) > 0.80d);

		double previous = 0;
		for (int step = 0; step <= 100; step++)
		{
			double current = ProceduralRenderer.severityResponse(step / 100.0d, 65);
			assertTrue(current + DELTA >= previous);
			previous = current;
		}

		assertEquals(0, ProceduralRenderer.distressResponse(0.20d), DELTA);
		assertTrue(ProceduralRenderer.distressResponse(0.60d) > 0);
		assertEquals(1, ProceduralRenderer.distressResponse(1), DELTA);
		assertEquals(0, ProceduralRenderer.activeBaseResponse(0), DELTA);
		assertTrue(ProceduralRenderer.activeBaseResponse(0.20d) > 0.20d);
		assertEquals(1, ProceduralRenderer.activeBaseResponse(1), DELTA);
	}

	@Test
	public void featherControlsOneMonotonicContour()
	{
		assertEquals(1, ProceduralRenderer.contourWeight(0, 100, 0), DELTA);
		assertEquals(0, ProceduralRenderer.contourWeight(100, 100, 0), DELTA);
		assertEquals(0, ProceduralRenderer.contourWeight(Double.NaN, 100, 50), DELTA);
		assertEquals(0, ProceduralRenderer.contourWeight(20, -1, 50), DELTA);

		double crispMiddle = ProceduralRenderer.contourWeight(50, 100, 0);
		double softMiddle = ProceduralRenderer.contourWeight(50, 100, 100);
		assertEquals(1, crispMiddle, DELTA);
		assertTrue(softMiddle < crispMiddle);

		for (int feather : new int[] {0, 25, 75, 100})
		{
			double previous = 1;
			for (int depth = 0; depth <= 100; depth++)
			{
				double current = ProceduralRenderer.contourWeight(depth, 100, feather);
				assertTrue(current <= previous + DELTA);
				previous = current;
			}
		}

	}

	@Test
	public void contourIsAnExactRoundedRectangleWithFlatSides()
	{
		int width = 321;
		int height = 183;
		double centerX = (width - 1) * 0.5d;
		double centerY = (height - 1) * 0.5d;
		double radius = CONTOUR_CORNER_RADIUS_FRACTION * Math.min(centerX, centerY);
		double flatHalfWidth = centerX - radius;
		double flatHalfHeight = centerY - radius;

		assertEquals(0, contourDepth(width, height, 0, centerY), DELTA);
		assertEquals(0, contourDepth(width, height, width - 1, centerY), DELTA);
		assertEquals(0, contourDepth(width, height, 0, centerY - flatHalfHeight * 0.75d), DELTA);
		assertEquals(0, contourDepth(width, height, 0, centerY + flatHalfHeight * 0.75d), DELTA);
		assertEquals(0, contourDepth(width, height, centerX - flatHalfWidth * 0.75d, 0), DELTA);
		assertEquals(0, contourDepth(width, height, centerX + flatHalfWidth * 0.75d, 0), DELTA);

		assertEquals(20, contourDepth(width, height, 20, centerY), DELTA);
		assertEquals(20, contourDepth(width, height, centerX, 20), DELTA);
		assertEquals(Math.min(centerX, centerY), contourDepth(width, height, centerX, centerY), DELTA);

		double arcOffset = radius / Math.sqrt(2);
		double arcX = centerX + flatHalfWidth + arcOffset;
		double arcY = centerY + flatHalfHeight + arcOffset;
		assertEquals(0, contourDepth(width, height, arcX, arcY), DELTA);

		double expectedCornerDepth = radius * (1 - Math.sqrt(2));
		assertEquals(expectedCornerDepth, contourDepth(width, height, 0, 0), DELTA);
		assertEquals(expectedCornerDepth, contourDepth(width, height, width - 1, height - 1), DELTA);
		assertEquals(
			contourDepth(width, height, 23.5d, 54.25d),
			contourDepth(width, height, width - 1 - 23.5d, height - 1 - 54.25d),
			DELTA);
	}

	@Test
	public void cornerOpacityKeepsFlatSidesStrongAndRaisesOnlyRoundedCorners()
	{
		int width = 321;
		int height = 183;
		double centerX = (width - 1) * 0.5d;
		double centerY = (height - 1) * 0.5d;
		double radius = CONTOUR_CORNER_RADIUS_FRACTION * Math.min(centerX, centerY);
		double flatHalfWidth = centerX - radius;

		assertEquals(CONTOUR_SIDE_OPACITY,
			ProceduralRenderer.contourCornerOpacity(width, height, 0, centerY), DELTA);
		assertEquals(CONTOUR_SIDE_OPACITY,
			ProceduralRenderer.contourCornerOpacity(width, height, centerX, 0), DELTA);
		assertEquals(CONTOUR_SIDE_OPACITY,
			ProceduralRenderer.contourCornerOpacity(
				width,
				height,
				centerX + flatHalfWidth * 0.75d,
				0), DELTA);
		assertEquals(1, ProceduralRenderer.contourCornerOpacity(width, height, 0, 0), DELTA);
		assertEquals(1,
			ProceduralRenderer.contourCornerOpacity(width, height, width - 1, height - 1), DELTA);

		double halfwayX = centerX + flatHalfWidth + radius * 0.5d;
		double halfwayDepth = contourDepth(width, height, halfwayX, 0);
		double maximumOutsideDepth = radius * (Math.sqrt(2) - 1);
		double cornerProgress = Math.min(1, Math.max(0, -halfwayDepth / maximumOutsideDepth));
		double expectedHalfwayOpacity = CONTOUR_SIDE_OPACITY
			+ (1 - CONTOUR_SIDE_OPACITY) * smootherstepForTest(cornerProgress);
		double halfwayOpacity = ProceduralRenderer.contourCornerOpacity(
			width,
			height,
			halfwayX,
			0);
		assertEquals(expectedHalfwayOpacity, halfwayOpacity, DELTA);
		assertTrue(halfwayOpacity > CONTOUR_SIDE_OPACITY);
		assertTrue(halfwayOpacity < 1);

		double previous = CONTOUR_SIDE_OPACITY;
		for (int step = 0; step <= 32; step++)
		{
			double x = centerX + centerX * step / 32.0d;
			double current = ProceduralRenderer.contourCornerOpacity(width, height, x, 0);
			assertTrue("Corner opacity fell at step " + step, current + DELTA >= previous);
			assertTrue(current >= CONTOUR_SIDE_OPACITY - DELTA);
			assertTrue(current <= 1 + DELTA);
			previous = current;
		}
	}

