	@Test
	public void sampledTransformMatchesEquivalentCanvasTransform()
	{
		int canvasWidth = 337;
		int canvasHeight = 193;
		int sampledWidth = 113;
		int sampledHeight = 65;
		double scaleX = canvasWidth / (double) sampledWidth;
		double scaleY = canvasHeight / (double) sampledHeight;

		AffineTransform canvasTransform = new AffineTransform();
		canvasTransform.translate(174.5d, 92.0d);
		canvasTransform.rotate(0.13d);
		canvasTransform.scale(1.08d, 0.96d);
		canvasTransform.translate(-168.5d, -96.5d);
		AffineTransform sampledTransform = ProceduralRenderer.toSampledTransform(
			canvasTransform,
			canvasWidth,
			canvasHeight,
			sampledWidth,
			sampledHeight);

		Point2D.Double[] points =
		{
			new Point2D.Double(0, 0),
			new Point2D.Double(24.25d, 17.75d),
			new Point2D.Double(sampledWidth - 1, sampledHeight - 1)
		};
		for (Point2D.Double sampledPoint : points)
		{
			Point2D expected = canvasTransform.transform(
				new Point2D.Double(sampledPoint.x * scaleX, sampledPoint.y * scaleY),
				null);
			Point2D actualSampled = sampledTransform.transform(sampledPoint, null);
			assertEquals(expected.getX(), actualSampled.getX() * scaleX, DELTA);
			assertEquals(expected.getY(), actualSampled.getY() * scaleY, DELTA);
		}

		assertTrue(ProceduralRenderer.toSampledTransform(
			null,
			canvasWidth,
			canvasHeight,
			sampledWidth,
			sampledHeight).isIdentity());
	}

	@Test
