		BufferedImage actual = renderTransparent(
			reused,
			effects(StatusEffect.FREEZE, 0.82d),
			STATIC_CONFIG,
			1.75d);
		BufferedImage expected = renderTransparent(
			effects(StatusEffect.FREEZE, 0.82d),
			STATIC_CONFIG,
