		assertArrayEquals(pixels(expected), pixels(actual));
	}

	@Test
	public void stableCompositionsReuseOneFullResolutionUpscale()
	{
		ProceduralRenderer renderer = new ProceduralRenderer();
		StatusEffects poison = effects(StatusEffect.POISON, 0.82d);
		BufferedImage first = renderTransparent(renderer, poison, STATIC_CONFIG, 0);
		BufferedImage second = renderTransparent(renderer, poison, STATIC_CONFIG, 9999);

		assertArrayEquals(pixels(first), pixels(second));
		assertEquals(1, renderer.getStableUpscaleBuildCount());

		renderTransparent(renderer, effects(StatusEffect.POISON, 0.91d), STATIC_CONFIG, 9999);
		assertEquals(2, renderer.getStableUpscaleBuildCount());

		renderTransparent(renderer, poison, MAX_MOTION_CONFIG, 9999);
		assertEquals(2, renderer.getStableUpscaleBuildCount());
	}

