		StatusEffects poison = effects(StatusEffect.POISON, 0.82d);
		render(reused, WIDTH, HEIGHT, poison, STATIC_CONFIG, 0, 0xff17120f);
		BufferedImage actual = render(reused, WIDTH, HEIGHT, poison, STATIC_CONFIG, 9999, 0xff213047);
		BufferedImage expected = render(WIDTH, HEIGHT, poison, STATIC_CONFIG, 9999, 0xff213047);

		assertArrayEquals(pixels(expected), pixels(actual));
		assertEquals(1, reused.getStableUpscaleBuildCount());
	}

	@Test
	public void staticFreezeCanCacheAtMaximumMotionButTransientsDoNot()
	{
		ProceduralRenderer freezeRenderer = new ProceduralRenderer();
		StatusEffects freeze = effects(StatusEffect.FREEZE, 1.0d);
		renderTransparent(freezeRenderer, freeze, MAX_MOTION_CONFIG, 0);
		renderTransparent(freezeRenderer, freeze, MAX_MOTION_CONFIG, 9999);
		assertEquals(1, freezeRenderer.getStableUpscaleBuildCount());
		assertEquals(1, freezeRenderer.getFreezeDetailBuildCount());
		assertEquals((long) WIDTH * HEIGHT, freezeRenderer.getFreezeDetailPixelCount());
		renderTransparent(freezeRenderer, StatusEffects.NONE, MAX_MOTION_CONFIG, 9999);
		assertEquals(0, freezeRenderer.getFreezeDetailPixelCount());

		ProceduralRenderer transientRenderer = new ProceduralRenderer();
		StatusEffects damage = effects(StatusEffect.DAMAGE, 1.0d);
		renderTransparent(transientRenderer, damage, STATIC_CONFIG, 0);
		renderTransparent(transientRenderer, damage, STATIC_CONFIG, 0);
		assertEquals(0, transientRenderer.getStableUpscaleBuildCount());
	}

