	@Test
	public void expandedEffectStackAddressesAndRendersEveryChannel()
	{
		for (StatusEffect active : StatusEffect.values())
		{
			StatusEffects channel = effects(active, 0.73d);
			assertEquals(0.73d, channel.get(active), DELTA);
			assertFalse(channel.isEmpty());

			for (StatusEffect other : StatusEffect.values())
			{
				if (other != active)
				{
					assertEquals(0, channel.get(other), DELTA);
				}
			}

			BufferedImage rendered = renderTransparent(channel, NO_FLASH_CONFIG, 0.25d);
			assertTrue("No rendered pixels for " + active, alphaSum(rendered) > 0);
		}
	}

	@Test
	public void everyEffectUsesAContinuousEdgeAndClearCenter()
	{
		for (EffectPreview preview : activePreviews())
		{
			BufferedImage image = render(StatusEffects.preview(preview), STATIC_CONFIG, 3.0);
			assertEquals("Center changed for " + preview, BACKGROUND, image.getRGB(WIDTH / 2, HEIGHT / 2));
			assertTrue("Edge did not change for " + preview, changedBorderPixelCount(image, 32) > 100);
			assertOuterPerimeterChanged(image, BACKGROUND);
		}
	}

	@Test
	public void oddCanvasHasNoFormerBandJoinOrCornerHole()
	{
		int width = 337;
		int height = 193;
		BufferedImage image = render(
			width,
			height,
			StatusEffects.preview(EffectPreview.POISON),
			STATIC_CONFIG,
			0,
			0);
		assertOuterPerimeterChanged(image, 0);

		for (int x : new int[] {0, 1, width / 2, width - 2, width - 1})
		{
			assertTrue(alpha(image.getRGB(x, 0)) > 0);
			assertTrue(alpha(image.getRGB(x, height - 1)) > 0);
		}
		for (int y : new int[] {0, 1, height / 2, height - 2, height - 1})
		{
			assertTrue(alpha(image.getRGB(0, y)) > 0);
			assertTrue(alpha(image.getRGB(width - 1, y)) > 0);
		}
	}

