	@Test
	public void damageFlashFadeProvidesSmoothSixtyHertzAlphaProgression()
	{
		int durationMillis = 650;
		ImpactTracker tracker = new ImpactTracker();
		assertTrue(tracker.triggerSeverity(1.0d, 0, durationMillis));
		ProceduralRenderer renderer = new ProceduralRenderer();
		boolean[] observedAlpha = new boolean[256];
		int previousAlpha = 256;
		int peakAlpha = 0;
		int finalAlpha = -1;
		for (int frame = 0; frame <= 39; frame++)
		{
			long nowNanos = frame * 1_000_000_000L / 60L;
			double strength = tracker.strength(nowNanos, durationMillis, 100);
			BufferedImage image = renderTransparent(
				renderer,
				effects(StatusEffect.DAMAGE, strength),
				FULL_FLASH_CONFIG,
				nowNanos / 1_000_000_000.0d);
			int currentAlpha = alpha(image.getRGB(WIDTH / 2, HEIGHT / 2));
			assertTrue("Flash alpha increased at frame " + frame, currentAlpha <= previousAlpha);
			observedAlpha[currentAlpha] = true;
			peakAlpha = Math.max(peakAlpha, currentAlpha);
			previousAlpha = currentAlpha;
			finalAlpha = currentAlpha;
		}

		int distinctLevels = 0;
		for (boolean observed : observedAlpha)
		{
			if (observed)
			{
				distinctLevels++;
			}
		}
		assertEquals(255, peakAlpha);
		assertEquals(0, finalAlpha);
		assertTrue("Distinct center alpha levels: " + distinctLevels, distinctLevels >= 35);
	}

