	@Test
	public void prayerUsesNearWhiteAntialiasedSymbolsOverPurpleVignette()
	{
		int width = 640;
		int height = 360;
		StatusEffects prayer = effects(StatusEffect.LOW_PRAYER, 1.0d);
		BufferedImage vignetteOnly = render(
			width,
			height,
			prayer,
			prayerConfig(new Color(0, 0, 0, 0)),
			0,
			0);
		BufferedImage withSymbols = render(
			width,
			height,
			prayer,
			prayerConfig(PRAYER_SYMBOL),
			0,
			0);

		int purplePixels = 0;
		int nearWhitePixels = 0;
		int intermediateSymbolPixels = 0;
		int closestSymbolDistance = Integer.MAX_VALUE;
		int[] vignettePixels = pixels(vignetteOnly);
		int[] symbolPixels = pixels(withSymbols);
		for (int i = 0; i < symbolPixels.length; i++)
		{
			Color vignette = new Color(vignettePixels[i], true);
			Color symbol = new Color(symbolPixels[i], true);
			if (vignette.getAlpha() > 12
				&& vignette.getBlue() > vignette.getRed() + 15
				&& vignette.getRed() > vignette.getGreen())
			{
				purplePixels++;
			}

			int configuredDistance = Math.abs(symbol.getRed() - PRAYER_SYMBOL.getRed())
				+ Math.abs(symbol.getGreen() - PRAYER_SYMBOL.getGreen())
				+ Math.abs(symbol.getBlue() - PRAYER_SYMBOL.getBlue());
			closestSymbolDistance = Math.min(closestSymbolDistance, configuredDistance);
			if (symbol.getAlpha() > 180
				&& symbol.getRed() >= 225
				&& symbol.getGreen() >= 230
				&& symbol.getBlue() >= 225)
			{
				nearWhitePixels++;
			}

			int difference = pixelDistance(vignettePixels[i], symbolPixels[i]);
			if (difference >= 6 && difference <= 220)
			{
				intermediateSymbolPixels++;
			}
		}

		assertTrue("Purple pixels: " + purplePixels, purplePixels > 2_000);
		assertTrue("Near-white pixels: " + nearWhitePixels, nearWhitePixels > 40);
		assertTrue("Closest symbol distance: " + closestSymbolDistance, closestSymbolDistance < 24);
		assertTrue("Intermediate symbol pixels: " + intermediateSymbolPixels, intermediateSymbolPixels > 100);
	}

