	@Test
	public void cachedBloodGeometryStaysStableAcrossCoverageChanges()
	{
		int width = 640;
		int height = 360;
		StatusEffects health = effects(StatusEffect.LOW_HEALTH, 1.0d);
		ProceduralRenderer renderer = new ProceduralRenderer();
		BufferedImage baseline = render(width, height, health, bloodConfig(0, 0), 0, 0);
		BufferedImage lowFirst = render(renderer, width, height, health, bloodConfig(0, 35), 0, 0);
		BufferedImage high = render(renderer, width, height, health, bloodConfig(0, 100), 0, 0);
		BufferedImage lowAgain = render(renderer, width, height, health, bloodConfig(0, 35), 0, 0);
		BufferedImage freshLow = render(width, height, health, bloodConfig(0, 35), 0, 0);

		assertArrayEquals(pixels(lowFirst), pixels(lowAgain));
		assertArrayEquals(pixels(freshLow), pixels(lowAgain));

		int lowFootprint = 0;
		int highFootprint = 0;
		int lowPixelsMissingAtHighCoverage = 0;
		int[] baselinePixels = pixels(baseline);
		int[] lowPixels = pixels(lowFirst);
		int[] highPixels = pixels(high);
		for (int index = 0; index < baselinePixels.length; index++)
		{
			boolean lowBlood = pixelDistance(baselinePixels[index], lowPixels[index]) > 8;
			boolean highBlood = pixelDistance(baselinePixels[index], highPixels[index]) > 8;
			if (lowBlood)
			{
				lowFootprint++;
				if (!highBlood)
				{
					lowPixelsMissingAtHighCoverage++;
				}
			}
			if (highBlood)
			{
				highFootprint++;
			}
		}

		assertTrue("Low-coverage blood footprint: " + lowFootprint, lowFootprint > 60);
		assertTrue("Coverage did not reveal more cached decals: " + lowFootprint + "/" + highFootprint,
			highFootprint > lowFootprint);
		assertEquals("Blood geometry disappeared when coverage increased",
			0,
			lowPixelsMissingAtHighCoverage);
	}

	@Test
	public void bloodDecalsStayFixedWhenAmbientMaterialMoves()
	{
		int width = 640;
		int height = 360;
		StatusEffects health = effects(StatusEffect.LOW_HEALTH, 1.0d);
		BufferedImage withoutDecals = render(width, height, health, bloodConfig(0, 0), 0, 0);
		BufferedImage fixedDecals = render(width, height, health, bloodConfig(0, 100), 0, 0);
		BufferedImage movingFirst = render(width, height, health, bloodConfig(100, 100), 0, 0);
		BufferedImage movingSecond = render(width, height, health, bloodConfig(100, 100), 4.0d, 0);

		int decalPixelsBeyondContour = 0;
		int antialiasedDecalPixels = 0;
		int fixedCorePixels = 0;
		int changedCorePixels = 0;
		int movingFootprintPixels = 0;
		int movingChangedPixels = 0;
		for (int y = 1; y < height - 1; y++)
		{
			for (int x = 1; x < width - 1; x++)
			{
				if (!isBeyondAtmosphericContour(width, height, x, y))
				{
					continue;
				}

				int baseline = withoutDecals.getRGB(x, y);
				int fixed = fixedDecals.getRGB(x, y);
				int first = movingFirst.getRGB(x, y);
				int second = movingSecond.getRGB(x, y);
				int decalDifference = pixelDistance(baseline, fixed);
				if (decalDifference > 8)
				{
					decalPixelsBeyondContour++;
				}
				if (decalDifference >= 8 && decalDifference <= 180)
				{
					antialiasedDecalPixels++;
				}

				if (isSolidDeltaCore(withoutDecals, fixedDecals, x, y, 80))
				{
					fixedCorePixels++;
					if (first != second)
					{
						changedCorePixels++;
					}
				}

				if (pixelDistance(baseline, first) > 8 || pixelDistance(baseline, second) > 8)
				{
					movingFootprintPixels++;
					if (first != second)
					{
						movingChangedPixels++;
					}
				}
			}
		}

		assertTrue("Decal pixels beyond contour: " + decalPixelsBeyondContour,
			decalPixelsBeyondContour > 100);
		assertTrue("Oversized decal footprint beyond contour: " + decalPixelsBeyondContour,
			decalPixelsBeyondContour < 1_600);
		assertTrue("Antialiased decal pixels: " + antialiasedDecalPixels,
			antialiasedDecalPixels > 12);
		assertTrue("Fixed core pixels: " + fixedCorePixels, fixedCorePixels > 30);
		assertTrue("Oversized fixed cores: " + fixedCorePixels, fixedCorePixels < 500);
		assertTrue("Changed core pixels: " + changedCorePixels,
			changedCorePixels * 2 < fixedCorePixels);
		assertTrue("Visible fixed blood footprint: " + movingFootprintPixels,
			movingFootprintPixels > 100);
		assertEquals("Ambient motion moved blood decals", 0, movingChangedPixels);
	}

