	private static StatusEffects effects(StatusEffect effect, double strength)
	{
		switch (effect)
		{
			case DISEASE:
				return new StatusEffects(strength, 0, 0, 0, 0, 0);
			case POISON:
				return new StatusEffects(0, strength, 0, 0, 0, 0);
			case VENOM:
				return new StatusEffects(0, 0, strength, 0, 0, 0);
			case LOW_PRAYER:
				return new StatusEffects(0, 0, 0, strength, 0, 0);
			case LOW_HEALTH:
				return new StatusEffects(0, 0, 0, 0, strength, 0);
			case FREEZE:
				return new StatusEffects(0, 0, 0, 0, 0, strength);
			case DAMAGE:
				return new StatusEffects(0, 0, 0, 0, 0, 0, strength, 0, 0);
			case POISON_TICK:
				return new StatusEffects(0, 0, 0, 0, 0, 0, 0, strength, 0);
			case VENOM_TICK:
				return new StatusEffects(0, 0, 0, 0, 0, 0, 0, 0, strength);
			default:
				return StatusEffects.NONE;
		}
