		int height = image.getHeight();
		for (int x = 0; x < width; x++)
		{
			assertNotEquals("Top perimeter hole at " + x, unchanged, image.getRGB(x, 0));
			assertNotEquals("Bottom perimeter hole at " + x, unchanged, image.getRGB(x, height - 1));
		}
		for (int y = 0; y < height; y++)
		{
			assertNotEquals("Left perimeter hole at " + y, unchanged, image.getRGB(0, y));
			assertNotEquals("Right perimeter hole at " + y, unchanged, image.getRGB(width - 1, y));
		}
	}

	private static void assertDepthRangeScales(int width, int height)
	{
		StatusEffects poison = effects(StatusEffect.POISON, 1.0d);
		BufferedImage shallow = render(
			width,
			height,
			poison,
			rendererConfig(4, 0, 0, 0, 100),
			0,
			0);
		BufferedImage deep = render(
			width,
			height,
			poison,
			rendererConfig(50, 0, 0, 0, 100),
			0,
			0);

		double shallowReach = maximumAlphaDepthFraction(shallow, 2, 4);
		double deepReach = maximumAlphaDepthFraction(deep, 2, 50);
		assertTrue("Shallow reach was " + shallowReach, shallowReach < 0.10d);
		assertTrue("Deep reach was " + deepReach, deepReach > 0.30d);
		assertTrue(deepReach > shallowReach + 0.24d);
		assertTrue(alpha(deep.getRGB(width / 2, height / 2)) <= 1);
	}

	private static double contourDepth(int width, int height, double x, double y)
	{
