	private static double healthSeverity(int healthPercent, int thresholdPercent)
	{
		return PlayerStatus.thresholdDangerStrength(
			healthPercent,
			100,
			thresholdPercent);
	}

	private static double smootherstepForTest(double value)
	{
		double bounded = Math.min(1, Math.max(0, value));
		return bounded * bounded * bounded * (bounded * (bounded * 6 - 15) + 10);
	}

	private static double maximumAlphaDepthFraction(
		BufferedImage image,
		int minimumAlpha,
		int depthPercent)
	{
		int width = image.getWidth();
		int height = image.getHeight();
		int shorter = Math.min(width, height);
		int requestedBand = (int) Math.round(shorter * depthPercent / 100.0d);
		int band = Math.max(1, Math.min(Math.max(1, shorter / 2 - 1), requestedBand));
		double cornerSmoothing = Math.max(1, band * 0.22d);
		double maximumDepth = 0;
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if (alpha(image.getRGB(x, y)) >= minimumAlpha)
				{
					double depth = ProceduralRenderer.contourDepth(
						width,
						height,
						x,
						y,
						cornerSmoothing);
					maximumDepth = Math.max(maximumDepth, depth);
				}
			}
		}
		return maximumDepth / (double) shorter;
	}

	private static int changedBorderPixelCount(BufferedImage image, int border)
	{
		int count = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((x < border || x >= image.getWidth() - border || y < border || y >= image.getHeight() - border)
					&& image.getRGB(x, y) != BACKGROUND)
				{
					count++;
				}
			}
		}
		return count;
	}

	private static long alphaSum(BufferedImage image)
	{
		long sum = 0;
		for (int pixel : pixels(image))
		{
			sum += alpha(pixel);
		}
		return sum;
	}

	private static int maximumAlpha(BufferedImage image)
	{
		int maximum = 0;
		for (int pixel : pixels(image))
		{
			maximum = Math.max(maximum, alpha(pixel));
		}
		return maximum;
	}

	private static int differingPixelCount(BufferedImage first, BufferedImage second)
	{
		assertEquals(first.getWidth(), second.getWidth());
		assertEquals(first.getHeight(), second.getHeight());
		int count = 0;
		int[] firstPixels = pixels(first);
		int[] secondPixels = pixels(second);
		for (int i = 0; i < firstPixels.length; i++)
		{
			if (firstPixels[i] != secondPixels[i])
			{
				count++;
			}
		}
		return count;
	}

	private static int maximumDeltaRun(
		BufferedImage baseline,
		BufferedImage changed,
		int minimumDistance)
	{
		assertEquals(baseline.getWidth(), changed.getWidth());
		assertEquals(baseline.getHeight(), changed.getHeight());
		int maximum = 0;
		for (int y = 0; y < baseline.getHeight(); y++)
		{
			int run = 0;
			for (int x = 0; x < baseline.getWidth(); x++)
			{
				if (pixelDistance(baseline.getRGB(x, y), changed.getRGB(x, y)) > minimumDistance)
				{
					run++;
					maximum = Math.max(maximum, run);
				}
				else
				{
					run = 0;
				}
			}
		}
		for (int x = 0; x < baseline.getWidth(); x++)
		{
			int run = 0;
			for (int y = 0; y < baseline.getHeight(); y++)
			{
				if (pixelDistance(baseline.getRGB(x, y), changed.getRGB(x, y)) > minimumDistance)
				{
					run++;
					maximum = Math.max(maximum, run);
				}
				else
				{
					run = 0;
				}
			}
		}
		return maximum;
	}

	private static boolean isBeyondAtmosphericContour(int width, int height, int x, int y)
	{
		int shorter = Math.min(width, height);
		int band = Math.max(1, (int) Math.round(shorter * 0.04d));
		double contourDepth = ProceduralRenderer.contourDepth(
			width,
			height,
			x,
			y,
			Math.max(1, band * 0.22d));
		return contourDepth > shorter * 0.09d;
	}

	private static boolean isSolidDeltaCore(
		BufferedImage baseline,
		BufferedImage decals,
		int x,
		int y,
		int minimumAlpha)
	{
		for (int offsetY = -1; offsetY <= 1; offsetY++)
		{
			for (int offsetX = -1; offsetX <= 1; offsetX++)
			{
				int baselineAlpha = alpha(baseline.getRGB(x + offsetX, y + offsetY));
				int decalAlpha = alpha(decals.getRGB(x + offsetX, y + offsetY));
				if (decalAlpha - baselineAlpha < minimumAlpha)
				{
					return false;
				}
			}
		}
		return true;
	}

	private static int pixelDistance(int first, int second)
	{
		return Math.abs(alpha(first) - alpha(second))
			+ Math.abs((first >>> 16 & 0xff) - (second >>> 16 & 0xff))
			+ Math.abs((first >>> 8 & 0xff) - (second >>> 8 & 0xff))
			+ Math.abs((first & 0xff) - (second & 0xff));
	}

	private static int pixelCountAtLeast(BufferedImage image, int minimumAlpha)
	{
		int count = 0;
		for (int pixel : pixels(image))
		{
			if (alpha(pixel) >= minimumAlpha)
			{
				count++;
			}
		}
		return count;
	}

	private static int alpha(int pixel)
	{
		return pixel >>> 24;
	}

	private static int[] pixels(BufferedImage image)
	{
		return ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
	}
}

package com.healthstatusoverlays;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class PlayerStatusTest
{
	private static final double DELTA = 0.000_001d;

	@Test
	public void negativePoisonValuesRepresentImmunity()
	{
		PlayerStatus poisonImmunity = status(-38);
		assertTrue(poisonImmunity.hasPoisonImmunity());
		assertFalse(poisonImmunity.hasVenomImmunity());
		assertEquals(1_140, poisonImmunity.immunityTicks());
		assertFalse(poisonImmunity.isPoisoned());
		assertFalse(poisonImmunity.isVenomed());
		assertEquals(0, poisonImmunity.poisonDamage());

		PlayerStatus venomImmunity = status(-40);
		assertTrue(venomImmunity.hasPoisonImmunity());
		assertTrue(venomImmunity.hasVenomImmunity());
		assertEquals(60, venomImmunity.immunityTicks());
	}

	@Test
	public void poisonDamageRoundsUpByFive()
	{
		assertEquals(1, status(1).poisonDamage());
		assertEquals(1, status(5).poisonDamage());
		assertEquals(2, status(6).poisonDamage());
		assertEquals(20, status(100).poisonDamage());
		assertEquals(0.10d, status(6).poisonStrength(), DELTA);
	}

	@Test
	public void venomStartsAtThresholdAndCapsAtTwentyDamage()
	{
		PlayerStatus belowThreshold = status(999_999);
		assertTrue(belowThreshold.isPoisoned());
		assertFalse(belowThreshold.isVenomed());

		assertEquals(6, status(1_000_000).venomDamage());
		assertEquals(8, status(1_000_001).venomDamage());
		assertEquals(20, status(1_000_007).venomDamage());
		assertEquals(20, status(Integer.MAX_VALUE).venomDamage());
		assertEquals(1.0d, status(Integer.MAX_VALUE).venomStrength(), DELTA);
	}

	@Test
	public void dangerThresholdHasAVisibleFloorAndClamps()
	{
		assertEquals(0.0d,
			PlayerStatus.thresholdDangerStrength(31, 100, 30), DELTA);
		assertEquals(PlayerStatus.VISIBLE_DANGER_FLOOR,
			PlayerStatus.thresholdDangerStrength(30, 100, 30), DELTA);

		double belowThreshold = PlayerStatus.thresholdDangerStrength(15, 100, 30);
		assertTrue(belowThreshold > PlayerStatus.VISIBLE_DANGER_FLOOR);
		assertTrue(belowThreshold < 1.0d);
		assertEquals(1.0d,
			PlayerStatus.thresholdDangerStrength(0, 100, 30), DELTA);
		assertEquals(1.0d,
			PlayerStatus.thresholdDangerStrength(-5, 100, 30), DELTA);
		assertEquals(0.0d,
			PlayerStatus.thresholdDangerStrength(0, 0, 30), DELTA);
		assertEquals(0.0d,
			PlayerStatus.thresholdDangerStrength(0, 100, 0), DELTA);
	}

	@Test
	public void percentageThresholdsWorkAtNonHundredMaximumsWithoutWarningAtFull()
	{
		assertEquals(0.0d,
			PlayerStatus.thresholdDangerStrength(57, 71, 80), DELTA);
		assertTrue(PlayerStatus.thresholdDangerStrength(49, 71, 80)
			> PlayerStatus.VISIBLE_DANGER_FLOOR);

		assertEquals(0.0d,
			PlayerStatus.thresholdDangerStrength(71, 71, 99), DELTA);
		assertTrue(PlayerStatus.thresholdDangerStrength(70, 71, 99)
			>= PlayerStatus.VISIBLE_DANGER_FLOOR);
	}

	@Test
	public void diseaseIsBinaryAndFreezeStrengthIsSanitized()
	{
		PlayerStatus clear = new PlayerStatus(0, 99, 99, 77, 77, 0, Double.NaN);
		assertFalse(clear.isDiseased());
		assertEquals(0.0d, clear.diseaseStrength(), DELTA);
		assertEquals(0.0d, clear.freezeStrength(), DELTA);

		PlayerStatus diseased = new PlayerStatus(0, 99, 99, 77, 77, 1, 4.0d);
		assertTrue(diseased.isDiseased());
		assertEquals(1.0d, diseased.diseaseStrength(), DELTA);
		assertEquals(1.0d, diseased.freezeStrength(), DELTA);
	}

	@Test
	public void snapshotKeepsRawValuesAndUsesPercentageThresholds()
	{
		PlayerStatus snapshot = new PlayerStatus(25, 14, 50, 4, 20, 7, 0.75d);
		assertEquals(25, snapshot.poisonValue());
		assertEquals(14, snapshot.health());
		assertEquals(50, snapshot.maximumHealth());
		assertEquals(4, snapshot.prayer());
		assertEquals(20, snapshot.maximumPrayer());
		assertEquals(7, snapshot.diseaseValue());
		assertTrue(snapshot.lowHealthStrength(30) > PlayerStatus.VISIBLE_DANGER_FLOOR);
		assertTrue(snapshot.lowPrayerStrength(25) > PlayerStatus.VISIBLE_DANGER_FLOOR);
	}

	private static PlayerStatus status(int poisonValue)
	{
		return new PlayerStatus(poisonValue, 99, 99, 77, 77, 0, 0.0d);
	}
}

package com.healthstatusoverlays;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.Arrays;
import org.junit.Test;

public class UpscalerTest
{
	@Test
	public void customPremultipliedUpscaleTracksJava2dBilinearReference()
	{
		assertCloseToReference(7, 5, 21, 15);
		assertCloseToReference(7, 5, 20, 14);
		assertCloseToReference(11, 8, 32, 23);
		assertCloseToReference(1, 1, 9, 7);
	}

	@Test
	public void upscaleOverwritesOldPixelsAndKeepsPremultipliedChannelsValid()
	{
		BufferedImage source = patternedImage(9, 6);
		BufferedImage target = new BufferedImage(27, 18, BufferedImage.TYPE_INT_ARGB_PRE);
		ProceduralRenderer renderer = new ProceduralRenderer();
		renderer.upscalePremultiplied(source, target);

		for (int pixel : pixels(target))
		{
			int alpha = pixel >>> 24;
			assertTrue(((pixel >>> 16) & 0xff) <= alpha);
			assertTrue(((pixel >>> 8) & 0xff) <= alpha);
			assertTrue((pixel & 0xff) <= alpha);
		}

		Arrays.fill(pixels(source), 0);
		renderer.upscalePremultiplied(source, target);
		for (int pixel : pixels(target))
		{
			assertEquals(0, pixel);
		}
	}

	private static void assertCloseToReference(
		int sourceWidth,
		int sourceHeight,
		int targetWidth,
		int targetHeight)
	{
		BufferedImage source = patternedImage(sourceWidth, sourceHeight);
		BufferedImage expected = new BufferedImage(targetWidth, targetHeight, BufferedImage.TYPE_INT_ARGB_PRE);
		Graphics2D graphics = expected.createGraphics();
		try
		{
			graphics.setComposite(AlphaComposite.Src);
			graphics.setRenderingHint(
				RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			graphics.drawImage(source, 0, 0, targetWidth, targetHeight, null);
		}
		finally
		{
			graphics.dispose();
		}

		BufferedImage actual = new BufferedImage(targetWidth, targetHeight, BufferedImage.TYPE_INT_ARGB_PRE);
		new ProceduralRenderer().upscalePremultiplied(source, actual);
		int maximumDelta = 0;
		int[] expectedPixels = pixels(expected);
		int[] actualPixels = pixels(actual);
		for (int index = 0; index < expectedPixels.length; index++)
		{
			for (int shift = 0; shift <= 24; shift += 8)
			{
				int expectedChannel = (expectedPixels[index] >>> shift) & 0xff;
				int actualChannel = (actualPixels[index] >>> shift) & 0xff;
				maximumDelta = Math.max(maximumDelta, Math.abs(expectedChannel - actualChannel));
			}
		}
		assertTrue("Maximum channel delta: " + maximumDelta, maximumDelta <= 2);
	}

	private static BufferedImage patternedImage(int width, int height)
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB_PRE);
		int[] pixels = pixels(image);
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int alpha = (x * 37 + y * 61 + 29) & 0xff;
				int red = alpha * ((x * 73 + y * 19 + 41) & 0xff) / 255;
				int green = alpha * ((x * 17 + y * 89 + 83) & 0xff) / 255;
				int blue = alpha * ((x * 53 + y * 31 + 127) & 0xff) / 255;
				pixels[y * width + x] = alpha << 24 | red << 16 | green << 8 | blue;
			}
		}
		return image;
	}

	private static int[] pixels(BufferedImage image)
	{
		return ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
	}
}

package com.healthstatusoverlays;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class ImpactTrackerTest
{
	private static final double DELTA = 0.000_001d;
	private static final long MILLIS = 1_000_000L;
	private static final int DURATION_MILLIS = 1_000;

	@Test
	public void firstObservationSeedsHealthWithoutCreatingAnImpact()
	{
		ImpactTracker tracker = new ImpactTracker();

		assertFalse(tracker.observeHealth(72, 99, 100L * MILLIS, DURATION_MILLIS));
		assertEquals(0.0d, tracker.strength(100L * MILLIS, DURATION_MILLIS, 100), DELTA);
		assertEquals(0.0d, tracker.strength(500L * MILLIS, DURATION_MILLIS, 100), DELTA);
	}

	@Test
	public void healthLossCreatesAnImpactScaledByDamageAndConfiguredStrength()
	{
		ImpactTracker tracker = new ImpactTracker();
		tracker.seedHealth(100);

		assertTrue(tracker.observeHealth(90, 100, 250L * MILLIS, DURATION_MILLIS));

		double peak = ImpactTracker.impactSeverity(10, 100);
		assertEquals(peak, tracker.strength(250L * MILLIS, DURATION_MILLIS, 100), DELTA);
		assertEquals(peak * 0.60d, tracker.strength(250L * MILLIS, DURATION_MILLIS, 60), DELTA);
	}

	@Test
	public void impactCurveMakesSmallHitsVisibleButReservesFullStrengthForLethalDamage()
	{
		double smallHit = ImpactTracker.impactSeverity(1, 100);
		double heavyHit = ImpactTracker.impactSeverity(35, 100);
		double nearlyLethal = ImpactTracker.impactSeverity(99, 100);

		double smallResponse = 1 - Math.pow(1 - 0.01d, 3);
		assertEquals(0.05d + 0.95d * smallResponse, smallHit, DELTA);
		assertTrue(smallHit > 0.05d);
		assertTrue(heavyHit > 0.70d);
		assertTrue(heavyHit > smallHit * 2.5d);
		assertTrue(smallHit < nearlyLethal);
		assertTrue(nearlyLethal < 1.0d);
		assertEquals(1.0d, ImpactTracker.impactSeverity(100, 100), DELTA);
		assertEquals(1.0d, ImpactTracker.impactSeverity(150, 100), DELTA);
	}

	@Test
	public void minimumResponseCanFollowHitSizeAloneOrMakeEveryHitLethalStrength()
	{
		double hitSizeOnly = 1 - Math.pow(1 - 0.01d, 3);
		assertEquals(hitSizeOnly,
			ImpactTracker.impactSeverity(1, 100, 0), DELTA);
		assertEquals(1.0d,
			ImpactTracker.impactSeverity(1, 100, 100), DELTA);
		assertEquals(1.0d,
			ImpactTracker.impactSeverity(100, 100, 0), DELTA);

		ImpactTracker proportional = new ImpactTracker();
		proportional.seedHealth(100);
		assertTrue(proportional.observeHealth(99, 100, 0, DURATION_MILLIS, 0));
		assertEquals(hitSizeOnly,
			proportional.strength(0, DURATION_MILLIS, 100), DELTA);

		ImpactTracker maximum = new ImpactTracker();
		maximum.seedHealth(100);
		assertTrue(maximum.observeHealth(99, 100, 0, DURATION_MILLIS, 100));
		assertEquals(1.0d,
			maximum.strength(0, DURATION_MILLIS, 100), DELTA);
	}

	@Test
	public void directDamageTriggerSupportsClassifiedToxinHitsWithoutAHealthBaseline()
	{
		ImpactTracker tracker = new ImpactTracker();

		assertTrue(tracker.triggerDamage(6, 100, 250L * MILLIS, DURATION_MILLIS));
		assertEquals(
			ImpactTracker.impactSeverity(6, 100),
			tracker.strength(250L * MILLIS, DURATION_MILLIS, 100),
			DELTA);
		assertFalse(tracker.triggerDamage(0, 100, 300L * MILLIS, DURATION_MILLIS));
		assertFalse(tracker.triggerDamage(6, 0, 300L * MILLIS, DURATION_MILLIS));
	}

	@Test
	public void healingDoesNotCreateAnImpactAndBecomesTheNextDamageBaseline()
	{
		ImpactTracker tracker = new ImpactTracker();
		tracker.seedHealth(80);

		assertFalse(tracker.observeHealth(95, 100, 0, DURATION_MILLIS));
		assertEquals(0.0d, tracker.strength(0, DURATION_MILLIS, 100), DELTA);
		assertTrue(tracker.observeHealth(90, 100, 2_000L * MILLIS, DURATION_MILLIS));
		assertEquals(
			ImpactTracker.impactSeverity(5, 100),
			tracker.strength(2_000L * MILLIS, DURATION_MILLIS, 100),
			DELTA);
	}

	@Test
	public void resetClearsTheImpactAndRequiresAFreshBaseline()
	{
		ImpactTracker tracker = new ImpactTracker();
		tracker.seedHealth(100);
		assertTrue(tracker.observeHealth(75, 100, 0, DURATION_MILLIS));

		tracker.reset();

		assertEquals(0.0d, tracker.strength(0, DURATION_MILLIS, 100), DELTA);
		assertFalse(tracker.observeHealth(50, 100, 100L * MILLIS, DURATION_MILLIS));
		assertEquals(0.0d, tracker.strength(100L * MILLIS, DURATION_MILLIS, 100), DELTA);
		assertTrue(tracker.observeHealth(40, 100, 200L * MILLIS, DURATION_MILLIS));
	}

	@Test
	public void impactDecaysMonotonicallyAndExpiresExactlyAtItsDuration()
	{
		ImpactTracker tracker = new ImpactTracker();
		tracker.seedHealth(100);
		tracker.observeHealth(70, 100, 1_000L * MILLIS, DURATION_MILLIS);

		double start = tracker.strength(1_000L * MILLIS, DURATION_MILLIS, 100);
		double quarter = tracker.strength(1_250L * MILLIS, DURATION_MILLIS, 100);
		double half = tracker.strength(1_500L * MILLIS, DURATION_MILLIS, 100);
		double threeQuarters = tracker.strength(1_750L * MILLIS, DURATION_MILLIS, 100);

		assertTrue(start > quarter);
		assertTrue(quarter > half);
		assertTrue(half > threeQuarters);
		assertTrue(threeQuarters > 0);
		assertEquals(0.0d, tracker.strength(2_000L * MILLIS, DURATION_MILLIS, 100), DELTA);
		assertEquals(0.0d, tracker.strength(2_500L * MILLIS, DURATION_MILLIS, 100), DELTA);
		assertEquals(0.0d, tracker.strength(999L * MILLIS, DURATION_MILLIS, 100), DELTA);
	}

	@Test
	public void repeatedHitsUnionTheRemainingImpactWithTheNewHit()
	{
		ImpactTracker tracker = new ImpactTracker();
		tracker.seedHealth(100);
		tracker.observeHealth(90, 100, 0, DURATION_MILLIS);

		double firstPeak = ImpactTracker.impactSeverity(10, 100);
		double remaining = firstPeak * ImpactTracker.decay(0.5d);
		assertEquals(remaining, tracker.strength(500L * MILLIS, DURATION_MILLIS, 100), DELTA);

		assertTrue(tracker.observeHealth(80, 100, 500L * MILLIS, DURATION_MILLIS));
		double expectedUnion = 1 - (1 - remaining) * (1 - firstPeak);
		double stackedPeak = tracker.strength(500L * MILLIS, DURATION_MILLIS, 100);
		assertEquals(expectedUnion, stackedPeak, DELTA);
		assertTrue(stackedPeak > firstPeak);
		assertTrue(stackedPeak <= 1.0d);
	}

	@Test
	public void invalidInputsDoNotCreateVisibleStrength()
	{
		ImpactTracker tracker = new ImpactTracker();
		tracker.seedHealth(100);

		assertFalse(tracker.observeHealth(90, 0, 0, DURATION_MILLIS));
		assertFalse(tracker.observeHealth(80, 100, -1, DURATION_MILLIS));
		assertEquals(0.0d, tracker.strength(0, 0, 100), DELTA);
		assertEquals(0.0d, tracker.strength(0, DURATION_MILLIS, 0), DELTA);
		assertEquals(0.0d, ImpactTracker.impactSeverity(0, 100), DELTA);
		assertEquals(0.0d, ImpactTracker.impactSeverity(10, 0), DELTA);
	}

	@Test
	public void previewLoopsThenLeavesAQuietGapBeforeRepeating()
	{
		int durationMillis = 650;
		int intervalSeconds = 2;
		int hitPercent = 15;
		int strengthPercent = 75;
		double expectedPeak = ImpactTracker.impactSeverity(hitPercent, 100) * 0.75d;

		assertEquals(expectedPeak, ImpactTracker.previewStrength(
			0, durationMillis, intervalSeconds, hitPercent, strengthPercent), DELTA);
		assertEquals(expectedPeak * 0.5d, ImpactTracker.previewStrength(
			325L * MILLIS, durationMillis, intervalSeconds, hitPercent, strengthPercent), DELTA);
		assertEquals(0.0d, ImpactTracker.previewStrength(
			650L * MILLIS, durationMillis, intervalSeconds, hitPercent, strengthPercent), DELTA);
		assertEquals(0.0d, ImpactTracker.previewStrength(
			1_999L * MILLIS, durationMillis, intervalSeconds, hitPercent, strengthPercent), DELTA);
		assertEquals(expectedPeak, ImpactTracker.previewStrength(
			2_000L * MILLIS, durationMillis, intervalSeconds, hitPercent, strengthPercent), DELTA);
	}

	@Test
	public void previewEnforcesAQuietGapWhenDurationExceedsTheRequestedInterval()
	{
		int durationMillis = 1_500;
		double expectedPeak = ImpactTracker.impactSeverity(30, 100);

		assertEquals(0.0d, ImpactTracker.previewStrength(
			1_500L * MILLIS, durationMillis, 1, 30, 100), DELTA);
		assertEquals(0.0d, ImpactTracker.previewStrength(
			1_749L * MILLIS, durationMillis, 1, 30, 100), DELTA);
		assertEquals(expectedPeak, ImpactTracker.previewStrength(
			1_750L * MILLIS, durationMillis, 1, 30, 100), DELTA);
	}

	@Test
	public void severityPreviewAppliesStrengthDecayClampingAndLoopTiming()
	{
		int durationMillis = 650;
		int intervalSeconds = 2;
		double severity = 0.80d;

		assertEquals(0.60d, ImpactTracker.previewSeverityStrength(
			0, durationMillis, intervalSeconds, severity, 75), DELTA);
		assertEquals(0.30d, ImpactTracker.previewSeverityStrength(
			325L * MILLIS, durationMillis, intervalSeconds, severity, 75), DELTA);
		assertEquals(0.0d, ImpactTracker.previewSeverityStrength(
			650L * MILLIS, durationMillis, intervalSeconds, severity, 75), DELTA);
		assertEquals(0.0d, ImpactTracker.previewSeverityStrength(
			1_999L * MILLIS, durationMillis, intervalSeconds, severity, 75), DELTA);
		assertEquals(0.60d, ImpactTracker.previewSeverityStrength(
			2_000L * MILLIS, durationMillis, intervalSeconds, severity, 75), DELTA);
		assertEquals(0.75d, ImpactTracker.previewSeverityStrength(
			0, durationMillis, intervalSeconds, 2.0d, 75), DELTA);
		assertEquals(0.0d, ImpactTracker.previewSeverityStrength(
			0, durationMillis, intervalSeconds, Double.NaN, 75), DELTA);
		assertEquals(0.0d, ImpactTracker.previewSeverityStrength(
			0, durationMillis, intervalSeconds, 0.8d, 0), DELTA);
	}
}

package com.healthstatusoverlays;

import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class HealthStatusOverlaysPluginLifecycleTest
{
	@Test
	public void startUpDefersClientReadsToClientThread()
	{
		Client client = mock(Client.class);
		ClientThread clientThread = mock(ClientThread.class);
		OverlayManager overlayManager = mock(OverlayManager.class);
		HealthStatusOverlay overlay = mock(HealthStatusOverlay.class);
		HealthStatusOverlaysConfig config = mock(HealthStatusOverlaysConfig.class);
		Player player = mock(Player.class);

		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);

		HealthStatusOverlaysPlugin plugin = new HealthStatusOverlaysPlugin();
		Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				bind(Client.class).toInstance(client);
				bind(ClientThread.class).toInstance(clientThread);
				bind(OverlayManager.class).toInstance(overlayManager);
				bind(HealthStatusOverlay.class).toInstance(overlay);
				bind(HealthStatusOverlaysConfig.class).toInstance(config);
			}
		}).injectMembers(plugin);

		plugin.startUp();

		verify(overlayManager).add(overlay);
		ArgumentCaptor<Runnable> action = ArgumentCaptor.forClass(Runnable.class);
		verify(clientThread).invoke(action.capture());
		verifyNoInteractions(client);

		action.getValue().run();

		verify(client, atLeastOnce()).getTickCount();
		verify(client).getLocalPlayer();
		verify(client).getGameState();
		verify(client, atLeastOnce()).getVarbitValue(anyInt());
	}
}

package com.healthstatusoverlays;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.gameval.SpotanimID;
import org.junit.Test;

public class FreezeTrackerTest
{
	private static final double DELTA = 0.000_001d;
	private static final long START_POSITION = 0x1234L;

	@Test
	public void chatConfirmationStartsThirtyTwoTickIceFallback()
	{
		FreezeTracker tracker = new FreezeTracker();
		tracker.confirmIce(100, START_POSITION);

		assertTrue(tracker.isActive());
		assertEquals(FreezeTracker.FreezeType.ICE_BARRAGE, tracker.type());
		assertEquals(32, tracker.durationTicks());
		assertEquals(132, tracker.expiryTick());
		assertEquals(32, tracker.remainingTicks());
		assertEquals(1.0d, tracker.strength(), DELTA);
	}

	@Test
	public void iceGraphicCannotStartTrackingByItself()
	{
		FreezeTracker tracker = new FreezeTracker();

		assertFalse(tracker.observeGraphic(SpotanimID.ICE_RUSH_IMPACT, 100, START_POSITION));
		assertFalse(tracker.isActive());
	}

	@Test
	public void sameTickIceGraphicRefinesFallbackDuration()
	{
		assertIceRefinement(SpotanimID.ICE_RUSH_IMPACT,
			FreezeTracker.FreezeType.ICE_RUSH, 8);
		assertIceRefinement(SpotanimID.ICE_BLITZ_IMPACT,
			FreezeTracker.FreezeType.ICE_BURST, 16);
		assertIceRefinement(SpotanimID.ICE_BURST_IMPACT,
			FreezeTracker.FreezeType.ICE_BLITZ, 24);
		assertIceRefinement(SpotanimID.ICE_BARRAGE_IMPACT,
			FreezeTracker.FreezeType.ICE_BARRAGE, 32);
	}

	@Test
	public void iceRefinementRequiresMatchingTickAndPosition()
	{
		FreezeTracker late = new FreezeTracker();
		late.confirmIce(100, START_POSITION);
		assertFalse(late.observeGraphic(SpotanimID.ICE_RUSH_IMPACT, 101, START_POSITION));
		assertEquals(32, late.durationTicks());

		FreezeTracker elsewhere = new FreezeTracker();
		elsewhere.confirmIce(100, START_POSITION);
		assertFalse(elsewhere.observeGraphic(SpotanimID.ICE_RUSH_IMPACT, 100, START_POSITION + 1));
		assertEquals(32, elsewhere.durationTicks());
	}

	@Test
	public void standardBindGraphicsStartDirectly()
	{
		assertDirectBind(SpotanimID.BIND_IMPACT,
			FreezeTracker.FreezeType.BIND, 8);
		assertDirectBind(SpotanimID.SNARE_IMPACT,
			FreezeTracker.FreezeType.SNARE, 16);
		assertDirectBind(SpotanimID.ENTANGLE_IMPACT,
			FreezeTracker.FreezeType.ENTANGLE, 24);
	}

	@Test
	public void movementClearsOnlyAfterApplicationTick()
	{
		FreezeTracker tracker = new FreezeTracker();
		tracker.observeGraphic(SpotanimID.ENTANGLE_IMPACT, 100, START_POSITION);

		tracker.advance(100, START_POSITION + 1);
		assertTrue(tracker.isActive());
		assertEquals(START_POSITION + 1, tracker.positionKey());

		tracker.advance(101, START_POSITION + 1);
		assertTrue(tracker.isActive());

		tracker.advance(102, START_POSITION + 2);
		assertFalse(tracker.isActive());
	}

	@Test
	public void expiryDeathLogoutAndResetClearTracking()
	{
		FreezeTracker tracker = new FreezeTracker();
		tracker.observeGraphic(SpotanimID.BIND_IMPACT, 100, START_POSITION);
		tracker.advance(107, START_POSITION);
		assertTrue(tracker.isActive());
		assertEquals(1, tracker.remainingTicks());
		tracker.advance(108, START_POSITION);
		assertFalse(tracker.isActive());

		tracker.confirmIce(200, START_POSITION);
		tracker.advance(200, START_POSITION, false, true);
		assertFalse(tracker.isActive());

		tracker.confirmIce(300, START_POSITION);
		tracker.advance(300, START_POSITION, true, false);
		assertFalse(tracker.isActive());

		tracker.confirmIce(400, START_POSITION);
		tracker.reset();
		assertFalse(tracker.isActive());
		assertEquals(0.0d, tracker.strength(), DELTA);
	}

	private static void assertIceRefinement(
		int graphicId,
		FreezeTracker.FreezeType expectedType,
		int expectedDuration)
	{
		FreezeTracker tracker = new FreezeTracker();
		tracker.confirmIce(100, START_POSITION);

		assertTrue(tracker.observeGraphic(graphicId, 100, START_POSITION));
		assertEquals(expectedType, tracker.type());
		assertEquals(expectedDuration, tracker.durationTicks());
		assertEquals(100 + expectedDuration, tracker.expiryTick());
	}

	private static void assertDirectBind(
		int graphicId,
		FreezeTracker.FreezeType expectedType,
		int expectedDuration)
	{
		FreezeTracker tracker = new FreezeTracker();

		assertTrue(tracker.observeGraphic(graphicId, 100, START_POSITION));
		assertEquals(expectedType, tracker.type());
		assertEquals(expectedDuration, tracker.durationTicks());
	}
}

