		assertTrue(mildPoison < 1.0d);

		config.previewPoisonDamage = 20;
		assertEquals(1.0d, effect(config, StatusEffect.POISON), DELTA);
		assertTrue(effect(config, StatusEffect.POISON) > mildPoison);

		config.preview = EffectPreview.VENOM;
		config.previewVenomDamage = 6;
