		assertEquals(venomSeverity(6), mildVenom, DELTA);
		assertTrue(mildVenom > 0.55d);
		assertTrue(mildVenom < 1.0d);

		config.previewVenomDamage = 20;
		assertEquals(1.0d, effect(config, StatusEffect.VENOM), DELTA);
		assertTrue(effect(config, StatusEffect.VENOM) > mildVenom);
	}

	@Test
	public void freezePreviewUsesTheConfiguredRemainingDuration()
	{
		TestConfig config = new TestConfig();
		config.preview = EffectPreview.FREEZE;
		config.previewFreezeRemaining = 0;

		assertEquals(0.0d, effect(config, StatusEffect.FREEZE), DELTA);

		config.previewFreezeRemaining = 100;
		assertEquals(1.0d, effect(config, StatusEffect.FREEZE), DELTA);
	}

	@Test
	public void diseasePreviewUsesTheConfiguredSeverity()
	{
		TestConfig config = new TestConfig();
		config.preview = EffectPreview.DISEASE;
		config.previewDiseaseSeverity = 37;

		assertEquals(0.37d, effect(config, StatusEffect.DISEASE), DELTA);
		assertFalse(HealthStatusOverlaysPlugin.previewEffects(config, 0).isEmpty());
	}

	@Test
	public void allPreviewCombinesEveryPersistentChannel()
	{
		TestConfig config = new TestConfig();
		config.preview = EffectPreview.ALL;
		config.previewDiseaseSeverity = 37;
		config.previewPoisonDamage = 4;
		config.previewVenomDamage = 12;
		config.lowPrayerThreshold = 20;
		config.previewPrayerPercent = 10;
		config.lowHealthThreshold = 50;
		config.previewHealthPercent = 25;
		config.previewFreezeRemaining = 50;

		StatusEffects effects = HealthStatusOverlaysPlugin.previewEffects(config, 0);
		assertEquals(0.37d, effects.get(StatusEffect.DISEASE), DELTA);
		assertEquals(poisonSeverity(4), effects.get(StatusEffect.POISON), DELTA);
		assertEquals(venomSeverity(12), effects.get(StatusEffect.VENOM), DELTA);
		assertEquals(
			PlayerStatus.thresholdDangerStrength(10, 100, 20),
			effects.get(StatusEffect.LOW_PRAYER),
			DELTA);
		assertEquals(
			PlayerStatus.thresholdDangerStrength(25, 100, 50),
			effects.get(StatusEffect.LOW_HEALTH),
			DELTA);
		assertEquals(0.70d, effects.get(StatusEffect.FREEZE), DELTA);
		assertEquals(0.0d, effects.get(StatusEffect.DAMAGE), DELTA);
		assertEquals(0.0d, effects.get(StatusEffect.POISON_TICK), DELTA);
		assertEquals(0.0d, effects.get(StatusEffect.VENOM_TICK), DELTA);
	}

	@Test
	public void replayPulsesUseDamageAndBothToxinTickChannels()
	{
		TestConfig config = new TestConfig();
		config.preview = EffectPreview.ALL;
		config.replayPreviewFeedback = true;
		config.previewDamageSize = 15;
		config.previewPoisonDamage = 6;
		config.previewVenomDamage = 10;

		StatusEffects effects = HealthStatusOverlaysPlugin.previewEffects(config, 0);
		assertEquals(previewPeak(config, 15), effects.get(StatusEffect.DAMAGE), DELTA);
		assertEquals(previewToxinPeak(config, 6, false), effects.get(StatusEffect.POISON_TICK), DELTA);
		assertEquals(previewToxinPeak(config, 10, true), effects.get(StatusEffect.VENOM_TICK), DELTA);

		config.preview = EffectPreview.POISON;
		effects = HealthStatusOverlaysPlugin.previewEffects(config, 0);
		assertEquals(previewToxinPeak(config, 6, false), effects.get(StatusEffect.POISON_TICK), DELTA);
		assertEquals(0.0d, effects.get(StatusEffect.VENOM_TICK), DELTA);

		config.preview = EffectPreview.VENOM;
		effects = HealthStatusOverlaysPlugin.previewEffects(config, 0);
		assertEquals(0.0d, effects.get(StatusEffect.POISON_TICK), DELTA);
		assertEquals(previewToxinPeak(config, 10, true), effects.get(StatusEffect.VENOM_TICK), DELTA);
	}

	@Test
	public void damageFeedbackPreviewReplaysEvenWhenReplayToggleIsOff()
	{
		TestConfig config = new TestConfig();
		config.preview = EffectPreview.DAMAGE_FEEDBACK;
		config.replayPreviewFeedback = false;
		config.previewDamageSize = 25;

		StatusEffects effects = HealthStatusOverlaysPlugin.previewEffects(config, 0);
		assertEquals(previewPeak(config, 25), effects.get(StatusEffect.DAMAGE), DELTA);
		assertEquals(0.0d, effects.get(StatusEffect.POISON_TICK), DELTA);
		assertEquals(0.0d, effects.get(StatusEffect.VENOM_TICK), DELTA);
	}

	@Test
	public void damageFeedbackPreviewUsesConfiguredSmallHitResponse()
	{
		TestConfig config = new TestConfig();
		config.preview = EffectPreview.DAMAGE_FEEDBACK;
		config.previewDamageSize = 1;
		config.damageFeedbackStrength = 100;
		config.damageMinimumResponse = 0;

		double proportional = effect(config, 0, StatusEffect.DAMAGE);
		assertEquals(
			ImpactTracker.impactSeverity(1, 100, 0),
			proportional,
			DELTA);

		config.damageMinimumResponse = 100;
		assertEquals(1.0d, effect(config, 0, StatusEffect.DAMAGE), DELTA);
		assertTrue(proportional < 1.0d);
	}

	@Test
	public void replayHasAQuietIntervalAndRestartsAtTheConfiguredInterval()
	{
		TestConfig config = new TestConfig();
		config.preview = EffectPreview.DAMAGE_FEEDBACK;
		config.replayPreviewFeedback = false;
		config.damageFeedbackDuration = 650;
		config.previewFeedbackInterval = 2;

		assertTrue(effect(config, 0, StatusEffect.DAMAGE) > 0);
		assertEquals(0.0d, effect(config, 650L * MILLIS, StatusEffect.DAMAGE), DELTA);
		assertEquals(0.0d, effect(config, 1_999L * MILLIS, StatusEffect.DAMAGE), DELTA);
		assertTrue(effect(config, 2_000L * MILLIS, StatusEffect.DAMAGE) > 0);
	}

	@Test
	public void requestedDefaultsUseTheTunedWarningAndMaterialValues()
	{
		HealthStatusOverlaysConfig defaults = new HealthStatusOverlaysConfig() { };
		assertEquals(75, defaults.lowHealthThreshold());
		assertEquals(50, defaults.lowPrayerThreshold());
		assertEquals(50, defaults.screenTint());
		assertEquals(25, defaults.motionStrength());
		assertEquals(85, defaults.damageFeedbackStrength());
		assertEquals(5, defaults.damageMinimumResponse());
		assertEquals(0x7f150631, defaults.lowPrayerColor().getRGB());
		assertEquals(245, defaults.lowHealthColor().getAlpha());
