	@Test
	public void debugPreviewMergesWithoutSuppressingLiveHealth()
	{
		StatusEffects live = new StatusEffects(0, 0, 0, 0, 0.44d, 0);
		StatusEffects preview = new StatusEffects(0, 0.70d, 0, 0, 0, 0.90d);
		StatusEffects merged = live.mergeMax(preview);

		assertEquals(0.44d, merged.get(StatusEffect.LOW_HEALTH), DELTA);
		assertEquals(0.70d, merged.get(StatusEffect.POISON), DELTA);
