	private static double effect(TestConfig config, StatusEffect effect)
	{
		return effect(config, 0, effect);
	}

	private static double effect(TestConfig config, long elapsedNanos, StatusEffect effect)
	{
		return HealthStatusOverlaysPlugin.previewEffects(config, elapsedNanos).get(effect);
	}

	private static double previewPeak(TestConfig config, int hitPercent)
	{
		return ImpactTracker.previewStrength(
			0,
			config.damageFeedbackDuration,
			config.previewFeedbackInterval,
			hitPercent,
			config.damageFeedbackStrength,
			config.damageMinimumResponse);
	}

	private static double previewToxinPeak(TestConfig config, int damage, boolean venom)
	{
		double persistent = venom ? venomSeverity(damage) : poisonSeverity(damage);
		double tickSeverity = 0.35d + 0.65d * persistent;
		return tickSeverity * config.damageFeedbackStrength / 100.0d;
	}

	private static double poisonSeverity(int damage)
	{
		return 0.60d + 0.40d * Math.max(0, Math.min(1, (damage - 1) / 19.0d));
	}

	private static double venomSeverity(int damage)
	{
		return 0.55d + 0.45d * Math.sqrt(Math.min(1, damage / 20.0d));
	}

	private static final class TestConfig implements HealthStatusOverlaysConfig
	{
		private EffectPreview preview = EffectPreview.OFF;
		private int lowHealthThreshold = 30;
		private int previewHealthPercent = 10;
		private int lowPrayerThreshold = 15;
		private int previewPrayerPercent = 5;
		private int previewPoisonDamage = 6;
		private int previewVenomDamage = 10;
		private int previewFreezeRemaining = 100;
		private int previewDiseaseSeverity = 48;
		private boolean replayPreviewFeedback;
		private int previewDamageSize = 15;
		private int previewFeedbackInterval = 2;
