package com.healthstatusoverlays;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class HealthAnimationTest
{
	private static final double DELTA = 0.000_001d;
	private static final int WIDTH = 640;
	private static final int HEIGHT = 360;

	@Test
	public void lowHealthCadenceAcceleratesOnWholeGameTicks()
	{
		assertEquals(4, pulseIntervalAtHealth(30));
		assertEquals(3, pulseIntervalAtHealth(20));
		assertEquals(2, pulseIntervalAtHealth(10));
		assertEquals(1, pulseIntervalAtHealth(0));

		int previousInterval = 1;
		for (int health = 0; health <= 30; health++)
		{
			int interval = pulseIntervalAtHealth(health);
			assertTrue("Pulse cadence slowed as health fell at " + health,
				interval >= previousInterval);
			previousInterval = interval;
		}
	}

	@Test
	public void gameTickClockInterpolatesWithinOneServerTick()
	{
		long startedNanos = 10_000_000_000L;
		assertEquals(123.0d,
			HealthStatusOverlaysPlugin.gameTickClock(123, startedNanos, startedNanos), DELTA);
		assertEquals(123.5d,
			HealthStatusOverlaysPlugin.gameTickClock(123, startedNanos, startedNanos + 300_000_000L), DELTA);

		double clamped = HealthStatusOverlaysPlugin.gameTickClock(
			123,
			startedNanos,
			startedNanos + 1_200_000_000L);
		assertTrue(clamped > 123.999d);
		assertTrue(clamped < 124.0d);
		assertEquals(123.0d,
			HealthStatusOverlaysPlugin.gameTickClock(123, -1, startedNanos), DELTA);
	}

	@Test
	public void zeroPulseStrengthKeepsHealthOpacitySteady()
	{
		double severity = healthSeverity(10);
		for (double gameTicks : new double[] {0, 0.25d, 1, 12.4d, 99_999.99d})
		{
			assertEquals(1.0d,
				ProceduralRenderer.healthPulse(gameTicks, severity, 0, 50), DELTA);
		}
	}

	@Test
	public void persistentHealthResponseSeparatesFiftyTenAndOnePercent()
	{
		double atThreshold = displayedHealthSeverity(75);
		double atFifty = displayedHealthSeverity(50);
		double atTen = displayedHealthSeverity(10);
		double atOne = displayedHealthSeverity(1);

		assertEquals("Threshold response", 0.32d, atThreshold, DELTA);
		assertTrue("50% response: " + atFifty, atFifty > 0.60d && atFifty < 0.61d);
		assertTrue("10% response: " + atTen, atTen > atFifty + 0.15d);
		assertTrue("1% response: " + atOne, atOne > atTen + 0.18d);
		assertTrue("Brink response: " + atOne, atOne > 0.99d);
	}

	@Test
	public void pulseStartsOnlyOnSelectedTicksAndDecaysSmoothly()
	{
		double severity = healthSeverity(20);
		int interval = ProceduralRenderer.healthPulseIntervalTicks(severity, 50);
		assertEquals(3, interval);

		double peak = ProceduralRenderer.healthPulse(6.0d, severity, 100, 50);
		double baseline = ProceduralRenderer.healthPulse(6.75d, severity, 100, 50);
		assertEquals(1.0d, peak, DELTA);
		assertTrue(baseline < peak);
		assertEquals(baseline,
			ProceduralRenderer.healthPulse(7.0d, severity, 100, 50), DELTA);
		assertEquals(baseline,
			ProceduralRenderer.healthPulse(8.0d, severity, 100, 50), DELTA);
		assertEquals(1.0d,
			ProceduralRenderer.healthPulse(9.0d, severity, 100, 50), DELTA);

		double previous = Double.POSITIVE_INFINITY;
		Set<Long> distinctValues = new HashSet<>();
		for (int step = 0; step <= 28; step++)
		{
			double phase = step * 0.025d;
			double current = ProceduralRenderer.healthPulse(
				6.0d + phase,
				severity,
				100,
				50);
			assertTrue("Pulse increased while fading at phase " + phase,
				current <= previous + DELTA);
			previous = current;
			distinctValues.add(Double.doubleToLongBits(current));
		}
		assertTrue("Distinct pulse levels: " + distinctValues.size(), distinctValues.size() >= 25);
		assertEquals(baseline, previous, DELTA);
	}

	@Test
	public void damageAloneNeverRevealsHealthBloodDecals()
	{
		StatusEffects damage = new StatusEffects(0, 0, 0, 0, 0, 0, 1, 0, 0);
		BufferedImage noBlood = render(damage, healthConfig(0, 0), 0, 0);
		BufferedImage maximumBlood = render(damage, healthConfig(100, 0), 0, 0);

		assertArrayEquals(pixels(noBlood), pixels(maximumBlood));
	}

	@Test
	public void persistentBloodMaskDoesNotFollowHeartbeatOpacity()
	{
		StatusEffects criticalHealth = new StatusEffects(0, 0, 0, 0, 1, 0);
		HealthStatusOverlaysConfig noBlood = healthConfig(0, 100);
		HealthStatusOverlaysConfig maximumBlood = healthConfig(100, 100);

		BufferedImage peakBaseline = render(criticalHealth, noBlood, 0, 6.0d);
		BufferedImage restBaseline = render(criticalHealth, noBlood, 0, 6.75d);
		BufferedImage peakBlood = render(criticalHealth, maximumBlood, 0, 6.0d);
		BufferedImage restBlood = render(criticalHealth, maximumBlood, 0, 6.75d);

		int footprint = 0;
		int maskUnion = 0;
		int maskMismatch = 0;
		int clearPixelMismatch = 0;
		for (int y = 0; y < HEIGHT; y++)
		{
			for (int x = 0; x < WIDTH; x++)
			{
				int peakBasePixel = peakBaseline.getRGB(x, y);
				int restBasePixel = restBaseline.getRGB(x, y);
				int peakBloodPixel = peakBlood.getRGB(x, y);
				int restBloodPixel = restBlood.getRGB(x, y);
				boolean peakDecal = peakBloodPixel != peakBasePixel;
				boolean restDecal = restBloodPixel != restBasePixel;
				if (peakDecal || restDecal)
				{
					maskUnion++;
				}
				if (peakDecal != restDecal)
				{
					maskMismatch++;
				}

				if (alpha(peakBasePixel) == 0 && alpha(restBasePixel) == 0
					&& (alpha(peakBloodPixel) > 0 || alpha(restBloodPixel) > 0))
				{
					footprint++;
					if (peakBloodPixel != restBloodPixel)
					{
						clearPixelMismatch++;
					}
				}
			}
		}

		assertTrue("Persistent blood footprint: " + footprint, footprint > 200);
		assertEquals("Blood changed on clear pixels between heartbeat phases", 0, clearPixelMismatch);
		assertTrue("Heartbeat changed blood mask: " + maskMismatch + "/" + maskUnion,
			maskUnion > 0 && maskMismatch * 100 <= maskUnion * 2);
	}

	private static int pulseIntervalAtHealth(int health)
	{
		return ProceduralRenderer.healthPulseIntervalTicks(
			healthSeverity(health),
			50);
	}

	private static double healthSeverity(int health)
	{
		return PlayerStatus.thresholdDangerStrength(health, 100, 30);
	}

	private static double displayedHealthSeverity(int health)
	{
		double rawSeverity = PlayerStatus.thresholdDangerStrength(
			health,
			100,
			75);
		return ProceduralRenderer.lowHealthSeverityResponse(rawSeverity, 65);
	}

	private static HealthStatusOverlaysConfig healthConfig(int splatter, int pulseStrength)
	{
		return new HealthStatusOverlaysConfig()
		{
			@Override
			public int effectIntensity()
			{
				return 100;
			}

			@Override
			public int edgeDepth()
			{
				return 4;
			}

			@Override
			public int dangerEscalation()
			{
				return 0;
			}

			@Override
			public int screenTint()
			{
				return 0;
			}

			@Override
			public int motionStrength()
			{
				return 0;
			}

			@Override
			public int healthPulseStrength()
			{
				return pulseStrength;
			}

			@Override
			public int healthPulseEscalation()
			{
				return 50;
			}

			@Override
			public int healthSplatter()
			{
				return splatter;
			}

			@Override
			public int damageFlash()
			{
				return 0;
			}

			@Override
			public Color lowHealthColor()
			{
				return new Color(154, 28, 34, 255);
			}
		};
	}

	private static BufferedImage render(
		StatusEffects effects,
		HealthStatusOverlaysConfig config,
		double animationSeconds,
		double gameTicks)
	{
		BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			new ProceduralRenderer().render(
				graphics,
				WIDTH,
				HEIGHT,
				effects,
				config,
				animationSeconds,
				gameTicks);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
