	private static int alpha(int pixel)
	{
		return pixel >>> 24;
	}

	private static int[] pixels(BufferedImage image)
	{
		return ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
	}
}

package com.healthstatusoverlays;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import org.junit.Test;

public class VignetteRegressionTest
{
	private static final double DELTA = 0.000_001d;
	private static final int WIDTH = 321;
	private static final int HEIGHT = 183;
	private static final double CENTER_X = (WIDTH - 1) * 0.5d;
	private static final double CENTER_Y = (HEIGHT - 1) * 0.5d;

	private static final HealthStatusOverlaysConfig STATIC_POISON_CONFIG = new HealthStatusOverlaysConfig()
	{
		@Override
		public int effectIntensity()
		{
			return 100;
		}

		@Override
		public int edgeDepth()
		{
			return 18;
		}

		@Override
		public int dangerEscalation()
		{
			return 0;
		}

		@Override
		public int screenTint()
		{
			return 0;
		}

		@Override
		public int motionStrength()
		{
			return 0;
		}

		@Override
		public Color poisonColor()
		{
			return new Color(99, 146, 47, 200);
		}
	};

	@Test
	public void signedRoundedRectangleDepthTracksSidesAndCorners()
	{
		assertEquals(0, depth(0, CENTER_Y), DELTA);
		assertEquals(0, depth(WIDTH - 1, CENTER_Y), DELTA);
		assertEquals(0, depth(CENTER_X, 0), DELTA);
		assertEquals(0, depth(CENTER_X, HEIGHT - 1), DELTA);
		assertEquals(20, depth(20, CENTER_Y), DELTA);
		assertEquals(20, depth(CENTER_X, 20), DELTA);
		assertEquals(CENTER_Y, depth(CENTER_X, CENTER_Y), DELTA);
		assertTrue(depth(0, 0) < 0);
		assertTrue(depth(WIDTH - 1, HEIGHT - 1) < 0);
	}

	@Test
	public void signedRoundedRectangleHasFlatSideSegments()
	{
		assertEquals(0, depth(CENTER_X, 0), DELTA);
		assertEquals(0, depth(80, 0), DELTA);
		assertEquals(0, depth(WIDTH - 1 - 80, 0), DELTA);
		assertEquals(0, depth(0, CENTER_Y), DELTA);
		assertEquals(0, depth(0, 60), DELTA);
	}

	@Test
	public void signedRoundedRectangleMaskIsReflectionSymmetric()
	{
		double[] xCoordinates = {0, 17, 64.5d, CENTER_X};
		double[] yCoordinates = {0, 11, 48.25d, CENTER_Y};
		for (double x : xCoordinates)
		{
			for (double y : yCoordinates)
			{
				double reflectedX = WIDTH - 1.0d - x;
				double reflectedY = HEIGHT - 1.0d - y;
				assertEquals(depth(x, y), depth(reflectedX, y), DELTA);
				assertEquals(depth(x, y), depth(x, reflectedY), DELTA);
				assertEquals(cornerOpacity(x, y), cornerOpacity(reflectedX, y), DELTA);
				assertEquals(cornerOpacity(x, y), cornerOpacity(x, reflectedY), DELTA);
			}
		}
	}

	@Test
	public void signedRoundedRectangleMaskIsScaleInvariant()
	{
		double depth = depth(40, 45);
		double scaledDepth = ProceduralRenderer.contourDepth(
			641,
			365,
			80,
			90,
			0);
		double opacity = cornerOpacity(40, 45);
		double scaledOpacity = ProceduralRenderer.contourCornerOpacity(
			641,
			365,
			80,
			90);

		assertEquals(depth * 2, scaledDepth, DELTA);
		assertEquals(opacity, scaledOpacity, DELTA);
		assertEquals(
			mask(depth, 60, 100, opacity),
			mask(scaledDepth, 120, 100, scaledOpacity),
			DELTA);
	}

	@Test
	public void cornersBecomeMoreOpaqueThanSideCenters()
	{
		double sideCenter = cornerOpacity(CENTER_X, 0);
		double betweenSideAndCorner = cornerOpacity(24, 0);
		double corner = cornerOpacity(0, 0);

		assertEquals(0.84d, sideCenter, DELTA);
		assertEquals(1, corner, DELTA);
		assertTrue(betweenSideAndCorner > sideCenter);
		assertTrue(betweenSideAndCorner < corner);
		assertTrue(corner - sideCenter >= 0.15d);
	}

	@Test
	public void featheredMaskFallsMonotonicallyTowardTheCenter()
	{
		int reach = 60;
		double previous = 1;
		for (int inset = 0; inset <= reach; inset++)
		{
			double depth = depth(CENTER_X, inset);
			double current = mask(depth, reach, 100, cornerOpacity(CENTER_X, inset));
			assertTrue("Mask increased at inset " + inset, current <= previous + DELTA);
			previous = current;
		}

		assertEquals(0.84d, mask(depth(CENTER_X, 0), reach, 100, cornerOpacity(CENTER_X, 0)), DELTA);
		assertEquals(0, mask(depth(CENTER_X, reach), reach, 100, cornerOpacity(CENTER_X, reach)), DELTA);
		assertEquals(0, mask(depth(CENTER_X, CENTER_Y), reach, 100, cornerOpacity(CENTER_X, CENTER_Y)), DELTA);
	}

	@Test
	public void staticProceduralRenderingIsDeterministic()
	{
		StatusEffects poison = new StatusEffects(0, 1, 0, 0, 0, 0);
		BufferedImage first = render(poison);
		BufferedImage second = render(poison);

		assertArrayEquals(pixels(first), pixels(second));
		assertTrue(nonTransparentPixelCount(first) > 0);
	}

	private static double depth(double x, double y)
	{
		return ProceduralRenderer.contourDepth(WIDTH, HEIGHT, x, y, 0);
	}

	private static double cornerOpacity(double x, double y)
	{
		return ProceduralRenderer.contourCornerOpacity(WIDTH, HEIGHT, x, y);
	}

	private static double mask(double depth, double reach, int feather, double cornerOpacity)
	{
		return ProceduralRenderer.contourWeight(depth, reach, feather) * cornerOpacity;
	}

	private static BufferedImage render(StatusEffects effects)
	{
		BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			new ProceduralRenderer().render(
				graphics,
				WIDTH,
				HEIGHT,
				effects,
				STATIC_POISON_CONFIG,
				0,
				0);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static int[] pixels(BufferedImage image)
	{
		return ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
	}

	private static int nonTransparentPixelCount(BufferedImage image)
	{
		int count = 0;
		for (int pixel : pixels(image))
		{
			if ((pixel >>> 24) != 0)
			{
				count++;
			}
		}
		return count;
	}
}

