final class ProceduralRenderer
{
	private static final int SAMPLE_STEP = 3;
	private static final int CENTER_FEATHER_PERCENT = 100;
	private static final double LOW_HEALTH_ONSET_PROGRESS = 0.40d;
	private static final double LOW_HEALTH_EDGE_ONSET = 0.32d;
	private static final double LOW_HEALTH_TINT_ONSET = 0.14d;
	private static final StatusEffect[] RENDER_ORDER =
	{
		StatusEffect.DISEASE,
		StatusEffect.POISON,
