	private final double[] frameRawSeverity = new double[RENDER_ORDER.length];
	private final double[] frameSeverity = new double[RENDER_ORDER.length];
	private final double[] frameBaseOpacity = new double[RENDER_ORDER.length];
	private final double[] frameDistressOpacity = new double[RENDER_ORDER.length];
	private final Color[] frameColors = new Color[RENDER_ORDER.length];
	private final ContourTexture[] frameTextures = new ContourTexture[RENDER_ORDER.length];
	private long cachedPixels;
	private BufferedImage sampledFrame;
	private Graphics2D sampledFrameGraphics;
	private BufferedImage stableUpscaledFrame;
	private int[] horizontalUpscalePixels;
	private int[] upscaleXLow;
	private int[] upscaleXHigh;
	private int[] upscaleXWeight;
	private int[] upscaleYLow;
	private int[] upscaleYHigh;
	private int[] upscaleYWeight;
	private int upscaleSourceWidth;
	private int upscaleSourceHeight;
	private int upscaleTargetWidth;
	private int upscaleTargetHeight;
	private boolean sampledCompositionValid;
	private boolean stableUpscaledFrameValid;
	private int stableUpscaleBuildCount;
	private int composedCanvasWidth;
	private int composedCanvasHeight;
	private int composedBand;
	private int composedFeather;
	private int composedTintOpacity;
	private int composedTintColor;
	private int composedFlashOpacity;
	private int composedFlashColor;
	private final int[] composedColors = new int[RENDER_ORDER.length];
	private final long[] composedSeverity = new long[RENDER_ORDER.length];
	private final int[] composedBaseOpacity = new int[RENDER_ORDER.length];
	private final int[] composedDistressOpacity = new int[RENDER_ORDER.length];
	private PrayerSymbolSet prayerSymbolSet;
	private FreezeCrystalSet freezeCrystalSet;
	private BufferedImage freezeDetailFrame;
	private boolean freezeDetailFrameValid;
	private long freezeDetailSeverity;
	private long freezeDetailMaster;
	private int freezeDetailColor;
	private int freezeDetailBuildCount;
	private BloodDecalSet bloodDecalSet;

	void render(
		Graphics2D graphics,
		int canvasWidth,
		int canvasHeight,
		StatusEffects effects,
		HealthStatusOverlaysConfig config,
		double animationSeconds)
	{
		render(
			graphics,
			canvasWidth,
			canvasHeight,
			effects,
			config,
			animationSeconds,
			animationSeconds / 0.6d);
	}

	void render(
		Graphics2D graphics,
		int canvasWidth,
		int canvasHeight,
		StatusEffects effects,
		HealthStatusOverlaysConfig config,
		double animationSeconds,
		double gameTicks)
	{
		if (freezeDetailFrame != null
			&& (effects == null || effects.get(StatusEffect.FREEZE) <= 0))
		{
			clearFreezeDetailFrame();
		}
		if (canvasWidth < 2 || canvasHeight < 2 || effects == null || effects.isEmpty())
		{
			return;
		}

		double master = clamp01(config.effectIntensity() / 100.0d);
		if (master <= 0)
		{
			clearFreezeDetailFrame();
			return;
		}

		double motion = clamp01(config.motionStrength() / 100.0d);
		double tickAlignedSeconds = Double.isFinite(gameTicks)
			? gameTicks * 0.6d
			: animationSeconds;
		int maximumBand = bandHeight(canvasWidth, canvasHeight, config.edgeDepth());
		if (maximumBand <= 0)
		{
			return;
		}

		double[] rawSeverity = frameRawSeverity;
		double[] severity = frameSeverity;
		double[] baseOpacity = frameBaseOpacity;
		double[] distressOpacity = frameDistressOpacity;
		Color[] colors = frameColors;
		ContourTexture[] textures = frameTextures;
		Arrays.fill(rawSeverity, 0);
		Arrays.fill(severity, 0);
		Arrays.fill(baseOpacity, 0);
		Arrays.fill(distressOpacity, 0);
		Arrays.fill(colors, null);
		Arrays.fill(textures, null);

		int dominantIndex = -1;
		int damageIndex = -1;
		int healthIndex = -1;
		int prayerIndex = -1;
		int freezeIndex = -1;
		double dominantScore = 0;
		for (int i = 0; i < RENDER_ORDER.length; i++)
		{
			StatusEffect effect = RENDER_ORDER[i];
			double rawEffectSeverity = effects.get(effect);
			if (rawEffectSeverity <= 0)
			{
				continue;
			}

			rawSeverity[i] = clamp01(rawEffectSeverity);
			double shapedSeverity;
			if (isTransient(effect))
			{
				shapedSeverity = rawSeverity[i];
			}
			else if (effect == StatusEffect.LOW_HEALTH)
			{
				shapedSeverity = lowHealthSeverityResponse(
					rawSeverity[i],
					config.dangerEscalation());
			}
			else
			{
				shapedSeverity = severityResponse(
					rawSeverity[i],
					config.dangerEscalation());
			}
			Color color = colorFor(effect, config);
			severity[i] = shapedSeverity;
			colors[i] = color;
			if (effect == StatusEffect.LOW_HEALTH)
			{
				healthIndex = i;
			}
			else if (effect == StatusEffect.LOW_PRAYER)
			{
				prayerIndex = i;
			}
			else if (effect == StatusEffect.FREEZE)
			{
				freezeIndex = i;
			}
			if (color.getAlpha() == 0)
			{
				continue;
			}

			double animation = animationFactor(effect, gameTicks, rawSeverity[i], config);
			baseOpacity[i] = isTransient(effect)
				? shapedSeverity
				: effect == StatusEffect.LOW_HEALTH
					? lowHealthBaseResponse(shapedSeverity)
					: activeBaseResponse(shapedSeverity);
			distressOpacity[i] = (isTransient(effect) ? shapedSeverity : distressResponse(shapedSeverity)) * animation;
			textures[i] = getContour(
				effect,
				canvasWidth,
				canvasHeight,
				maximumBand,
				CENTER_FEATHER_PERCENT,
				color);

			if (effect == StatusEffect.DAMAGE)
			{
				damageIndex = i;
			}

			double score = shapedSeverity * urgency(effect);
			if (contributesStatusTint(effect) && score > dominantScore)
			{
				dominantScore = score;
				dominantIndex = i;
			}
		}

		double tintOpacity = 0;
		if (dominantIndex >= 0)
		{
			tintOpacity = RENDER_ORDER[dominantIndex] == StatusEffect.LOW_HEALTH
				? lowHealthTintResponse(
					rawSeverity[dominantIndex],
					config.screenTint(),
					master)
				: tintResponse(severity[dominantIndex], config.screenTint()) * master;
		}

		double damageFlashOpacity = 0;
		if (damageIndex >= 0)
		{
			damageFlashOpacity = clamp01(config.damageFlash() / 100.0d) * severity[damageIndex] * master;
		}

		BufferedImage frame = prepareSampledFrame(canvasWidth, canvasHeight);
		Color tintFill = tintOpacity > 0 && dominantIndex >= 0
			? darken(colors[dominantIndex], 0.58d)
			: null;
		Color flashFill = damageFlashOpacity > 0 && damageIndex >= 0
			? darken(colors[damageIndex], 0.52d)
			: null;
		int tintColor = tintFill == null ? 0 : tintFill.getRGB();
		int flashColor = flashFill == null ? 0 : flashFill.getRGB();
		boolean timeStable = isSampledCompositionTimeStable(
			textures,
			motion,
			config.healthPulseStrength() > 0);
		boolean reuseComposition = timeStable && matchesSampledComposition(
			canvasWidth,
			canvasHeight,
			maximumBand,
			CENTER_FEATHER_PERCENT,
			tintOpacity,
			tintColor,
			damageFlashOpacity,
			flashColor,
			severity,
			baseOpacity,
			distressOpacity,
			colors,
			master);
		if (!reuseComposition)
		{
			Arrays.fill(((DataBufferInt) frame.getRaster().getDataBuffer()).getData(), 0);
			Graphics2D frameGraphics = sampledFrameGraphics;
			if (tintOpacity > 0 && dominantIndex >= 0)
			{
				frameGraphics.setComposite(AlphaComposite.getInstance(
					AlphaComposite.SRC_OVER,
					(float) tintOpacity));
				frameGraphics.setColor(tintFill);
				frameGraphics.fillRect(0, 0, frame.getWidth(), frame.getHeight());
			}

			if (damageFlashOpacity > 0 && damageIndex >= 0)
			{
				frameGraphics.setComposite(AlphaComposite.getInstance(
					AlphaComposite.SRC_OVER,
					(float) damageFlashOpacity));
				frameGraphics.setColor(flashFill);
				frameGraphics.fillRect(0, 0, frame.getWidth(), frame.getHeight());
			}

			for (int i = 0; i < RENDER_ORDER.length; i++)
			{
				ContourTexture texture = textures[i];
				if (texture == null)
				{
					continue;
				}

				if (baseOpacity[i] > 0)
				{
					frameGraphics.setComposite(AlphaComposite.getInstance(
						AlphaComposite.SRC_OVER,
						(float) (baseOpacity[i] * master)));
					frameGraphics.drawImage(texture.base, 0, 0, null);
				}

				if (distressOpacity[i] > 0)
				{
					frameGraphics.setComposite(AlphaComposite.getInstance(
						AlphaComposite.SRC_OVER,
						(float) (distressOpacity[i] * master)));
					AffineTransform canvasTransform = distressTransform(
						RENDER_ORDER[i],
						canvasWidth,
						canvasHeight,
						tickAlignedSeconds,
						severity[i],
						motion);
					AffineTransform sampledTransform = toSampledTransform(
						canvasTransform,
						canvasWidth,
						canvasHeight,
						frame.getWidth(),
						frame.getHeight());
					frameGraphics.drawImage(texture.distress, sampledTransform, null);
				}
			}

			if (timeStable)
			{
				rememberSampledComposition(
					canvasWidth,
					canvasHeight,
					maximumBand,
					CENTER_FEATHER_PERCENT,
					tintOpacity,
					tintColor,
					damageFlashOpacity,
					flashColor,
					severity,
					baseOpacity,
					distressOpacity,
					colors,
					master);
			}
			else
			{
				invalidateStableComposition();
			}
		}

		Graphics2D overlayGraphics = (Graphics2D) graphics.create();
		try
		{
			overlayGraphics.setClip(0, 0, canvasWidth, canvasHeight);
			overlayGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			overlayGraphics.setRenderingHint(
				RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);

			overlayGraphics.setComposite(AlphaComposite.SrcOver);
			overlayGraphics.drawImage(
				prepareUpscaledFrame(frame, canvasWidth, canvasHeight, timeStable),
				0,
				0,
				null);

			if (freezeIndex >= 0)
			{
				drawFreezeCrystals(
					overlayGraphics,
					canvasWidth,
					canvasHeight,
					severity[freezeIndex],
					master,
					config.freezeColor());
			}

			if (prayerIndex >= 0)
			{
				drawPrayerSymbols(
					overlayGraphics,
					canvasWidth,
					canvasHeight,
					severity[prayerIndex],
					master,
					motion,
					gameTicks,
					config.prayerSymbolColor());
			}

			double healthSeverity = healthIndex >= 0 ? rawSeverity[healthIndex] : 0;
			if (healthSeverity > 0 && config.healthSplatter() > 0)
			{
				drawBloodDecals(
					overlayGraphics,
					canvasWidth,
					canvasHeight,
					healthSeverity,
					master,
					config.healthSplatter(),
					config.lowHealthColor());
			}
		}
		finally
		{
			overlayGraphics.dispose();
		}
	}

	void clearCache()
	{
		contourCache.clear();
		cachedPixels = 0;
		invalidateStableComposition();
		prayerSymbolSet = null;
		freezeCrystalSet = null;
		clearFreezeDetailFrame();
		bloodDecalSet = null;
	}

