	{
		return contourCache.size();
	}

	long getCachedPixelCount()
	{
		return cachedPixels;
	}

	int getStableUpscaleBuildCount()
	{
		return stableUpscaleBuildCount;
	}

	int getFreezeDetailBuildCount()
	{
		return freezeDetailBuildCount;
	}

