	private ContourTexture getContour(
		StatusEffect effect,
		int canvasWidth,
		int canvasHeight,
		int band,
		int feather,
		Color color)
	{
		ContourKey key = new ContourKey(
			effect,
			canvasWidth,
			canvasHeight,
			band,
			boundedPercent(feather),
			color.getRGB());
		CachedContour cached = contourCache.get(effect);
		if (cached == null || !cached.key.equals(key))
		{
			if (cached != null)
			{
				cachedPixels -= cached.texture.pixelCount;
			}
			ContourTexture texture = generateContour(effect, canvasWidth, canvasHeight, band, feather, color);
			cached = new CachedContour(key, texture);
			contourCache.put(effect, cached);
			cachedPixels += texture.pixelCount;
		}
		return cached.texture;
	}

	private static ContourTexture generateContour(
		StatusEffect effect,
		int canvasWidth,
		int canvasHeight,
		int band,
		int feather,
		Color color)
	{
		int fieldWidth = Math.max(1, (canvasWidth + SAMPLE_STEP - 1) / SAMPLE_STEP);
		int fieldHeight = Math.max(1, (canvasHeight + SAMPLE_STEP - 1) / SAMPLE_STEP);
		BufferedImage base = new BufferedImage(fieldWidth, fieldHeight, BufferedImage.TYPE_INT_ARGB_PRE);
		BufferedImage distress = new BufferedImage(fieldWidth, fieldHeight, BufferedImage.TYPE_INT_ARGB_PRE);
		int[] basePixels = ((DataBufferInt) base.getRaster().getDataBuffer()).getData();
		int[] distressPixels = ((DataBufferInt) distress.getRaster().getDataBuffer()).getData();
		int seed = effect.getSeed();
		double materialScale = materialScale(canvasWidth, canvasHeight);
		double baseReach = Math.max(2, band * baseReachFraction(effect));
		int warpCell = scaledCell(176, materialScale);
		double warpDistance = domainWarp(effect) * materialScale;

		for (int y = 0; y < fieldHeight; y++)
		{
			double screenY = (y + 0.5d) * canvasHeight / fieldHeight - 0.5d;
			for (int x = 0; x < fieldWidth; x++)
			{
				double screenX = (x + 0.5d) * canvasWidth / fieldWidth - 0.5d;
				double depth = contourDepth(canvasWidth, canvasHeight, screenX, screenY, 0);
				double cornerOpacity = contourCornerOpacityForDepth(
					canvasWidth,
					canvasHeight,
					depth);
				double angle = Math.atan2(
					screenY - (canvasHeight - 1) * 0.5d,
					screenX - (canvasWidth - 1) * 0.5d);
				double silhouetteScale = effect == StatusEffect.FREEZE ? 0.42d : 1.0d;
				double silhouette = 0.050d * Math.sin(angle * 3 + seed * 0.17d)
					+ 0.035d * Math.sin(angle * 7 - seed * 0.11d)
					+ 0.080d * (valueNoise(
						screenX,
						screenY,
						scaledCell(260, materialScale),
						seed + 389) - 0.5d);
				depth += band * silhouetteScale * silhouette;
				if (depth >= band)
				{
					continue;
				}

				double warpX = (valueNoise(screenX, screenY, warpCell, seed + 211) - 0.5d) * warpDistance;
				double warpY = (valueNoise(screenX, screenY, warpCell, seed + 307) - 0.5d) * warpDistance;
				double sampleX = screenX + warpX;
				double sampleY = screenY + warpY;
				double coarse = fractalNoise(sampleX, sampleY, seed, materialScale);
				double fine = valueNoise(sampleX, sampleY, scaledCell(34, materialScale), seed + 101);
				double reachVariation = (coarse - 0.5d) * band * reachVariation(effect);
				double irregularDepth = depth + reachVariation;
				double baseMask = contourWeight(irregularDepth, baseReach, feather) * cornerOpacity;
				double distressMask = contourWeight(irregularDepth, band, feather) * cornerOpacity;
				if (baseMask <= 0 && distressMask <= 0)
				{
					continue;
				}

				double pattern = textureValue(
					effect,
					sampleX,
					sampleY,
					seed,
					coarse,
					fine,
					materialScale);
				double wash = baseWash(effect, sampleX, sampleY, seed, coarse, pattern, materialScale);
				double baseAmount = baseMask * baseMaterialAmount(effect, wash, pattern);
				double distressAmount = distressMask * distressMaterialAmount(effect, pattern);
				double dither = (hashUnit(x, y, seed + 401) - hashUnit(x, y, seed + 503)) * 0.75d;
				int baseAlpha = clamp255((int) Math.floor(color.getAlpha() * baseAmount + 0.5d + dither));
				int distressAlpha = clamp255((int) Math.floor(color.getAlpha() * distressAmount + 0.5d + dither));
				int index = y * fieldWidth + x;

				if (baseAlpha > 0)
				{
					double brightness = baseBrightness(effect, wash);
					basePixels[index] = coloredPixel(color, baseAlpha, brightness);
				}
				if (distressAlpha > 0)
				{
					double brightness = distressBrightness(effect, pattern);
					distressPixels[index] = coloredPixel(color, distressAlpha, brightness);
				}
			}
		}

		return new ContourTexture(base, distress);
	}

	private static double textureValue(
		StatusEffect effect,
		double x,
		double y,
		int seed,
		double coarse,
		double fine,
		double scale)
	{
		switch (effect)
		{
			case POISON:
			{
				double cells = worley(x, y, scaledCell(66, scale), seed + 17);
				double membrane = 1 - Math.min(1, Math.abs(cells - 0.46d) * 8.5d);
				return 0.18d * coarse + 0.57d * membrane + 0.25d * (1 - cells);
			}
			case POISON_TICK:
			{
				double cells = worley(x, y, scaledCell(58, scale), seed + 17);
				double membrane = 1 - Math.min(1, Math.abs(cells - 0.44d) * 9.0d);
				double droplets = bloodSpatterPattern(x, y, seed + 73, scale);
				return clamp01(0.06d + 0.54d * droplets + 0.30d * membrane + 0.10d * fine);
			}
			case VENOM:
			{
				double ridge = ridge(coarse);
				double crossRidge = ridge(valueNoise(
					x + y * 0.42d,
					y - x * 0.18d,
					scaledCell(82, scale),
					seed + 43));
				return 0.12d + 0.58d * Math.pow(ridge, 4) + 0.30d * Math.pow(crossRidge, 6);
			}
			case VENOM_TICK:
			{
				double tendril = Math.pow(ridge(coarse), 4);
				double droplets = bloodSpatterPattern(x, y, seed + 79, scale);
				return clamp01(0.07d + 0.46d * droplets + 0.47d * tendril);
			}
			case LOW_HEALTH:
			{
				double pressure = Math.pow(ridge(coarse), 10);
				double branch = Math.pow(ridge(valueNoise(
					x + y * 0.56d,
					y,
					scaledCell(74, scale),
					seed + 59)), 12);
				return clamp01(0.08d + 0.54d * pressure + 0.38d * branch);
			}
			case DAMAGE:
			{
				double pressure = Math.pow(ridge(coarse), 8);
				return clamp01(0.08d + 0.92d * pressure);
			}
			case LOW_PRAYER:
				return clamp01(0.12d + 0.58d * coarse);
			case DISEASE:
			{
				double cells = worley(x, y, scaledCell(92, scale), seed + 23);
				double stain = smoothstepRange(0.30d, 0.72d, coarse) * (1 - smoothstepRange(0.68d, 0.96d, cells));
				double speckle = fine > 0.78d ? 1 : 0;
				return 0.10d + 0.68d * stain + 0.22d * speckle;
			}
			case FREEZE:
				return clamp01(0.05d + 0.18d * coarse);
			default:
				return coarse;
		}
	}

	private static double bloodSpatterPattern(double x, double y, int seed, double scale)
	{
		double cellSize = scaledCell(96, scale);
		int cellX = (int) Math.floor(x / cellSize);
		int cellY = (int) Math.floor(y / cellSize);
		if (hashUnit(cellX, cellY, seed + 3) > 0.66d)
		{
			return 0;
		}

		double centerX = (cellX + 0.27d + 0.46d * hashUnit(cellX, cellY, seed + 5)) * cellSize;
		double centerY = (cellY + 0.27d + 0.46d * hashUnit(cellX, cellY, seed + 7)) * cellSize;
		double radiusX = (8 + 16 * hashUnit(cellX, cellY, seed + 11)) * scale;
		double radiusY = radiusX * (0.48d + 0.48d * hashUnit(cellX, cellY, seed + 13));
		double dx = x - centerX;
		double dy = y - centerY;
		double angle = Math.atan2(dy, dx);
		double irregularity = 0.82d + 0.18d * Math.sin(angle * 5 + seed);
		double normalized = Math.sqrt(dx * dx / (radiusX * radiusX) + dy * dy / (radiusY * radiusY)) / irregularity;
		double result = 1 - smoothstepRange(0.62d, 1.10d, normalized);

		for (int drop = 0; drop < 6; drop++)
		{
			double dropAngle = hashUnit(cellX, cellY, seed + 17 + drop * 7) * Math.PI * 2;
			double dropDistance = (12 + 18 * hashUnit(cellX, cellY, seed + 19 + drop * 7)) * scale;
			double dropRadius = (1.8d + 4.2d * hashUnit(cellX, cellY, seed + 23 + drop * 7)) * scale;
			double dropX = centerX + Math.cos(dropAngle) * dropDistance;
			double dropY = centerY + Math.sin(dropAngle) * dropDistance;
			double distance = Math.hypot(x - dropX, y - dropY);
			result = Math.max(result, 0.92d * (1 - smoothstepRange(dropRadius * 0.62d, dropRadius * 1.16d, distance)));
		}

		if (hashUnit(cellX, cellY, seed + 71) > 0.58d)
		{
			double smearAngle = hashUnit(cellX, cellY, seed + 73) * Math.PI * 2;
			double smearLength = (18 + 22 * hashUnit(cellX, cellY, seed + 79)) * scale;
			double smearDistance = pointToSegmentDistance(
				x,
				y,
				centerX,
				centerY,
				centerX + Math.cos(smearAngle) * smearLength,
				centerY + Math.sin(smearAngle) * smearLength);
			result = Math.max(result, 0.74d * (1 - smoothstepRange(1.0d * scale, 3.8d * scale, smearDistance)));
		}
		return clamp01(result);
	}

	static double materialScale(int width, int height)
	{
		if (width <= 0 || height <= 0)
		{
			return 0.80d;
		}
		return Math.max(0.80d, Math.min(2.40d, Math.min(width, height) / 720.0d));
	}

	private static double baseReachFraction(StatusEffect effect)
	{
		switch (effect)
		{
			case DAMAGE:
			case POISON_TICK:
			case VENOM_TICK:
				return 0.82d;
			case FREEZE:
				return 0.72d;
			case LOW_HEALTH:
				return 0.68d;
			case LOW_PRAYER:
				return 0.66d;
			default:
				return 0.62d;
		}
	}

	private static double domainWarp(StatusEffect effect)
	{
		switch (effect)
		{
			case FREEZE:
				return 6;
			case LOW_PRAYER:
				return 10;
			case DAMAGE:
				return 14;
			case LOW_HEALTH:
				return 24;
			default:
				return 34;
		}
	}

	private static double reachVariation(StatusEffect effect)
	{
		switch (effect)
		{
			case FREEZE:
				return 0.035d;
			case LOW_PRAYER:
				return 0.050d;
			case DAMAGE:
			case POISON_TICK:
			case VENOM_TICK:
				return 0.060d;
			default:
				return 0.110d;
		}
	}

	private static double baseWash(
		StatusEffect effect,
		double x,
		double y,
		int seed,
		double coarse,
		double pattern,
		double scale)
	{
		switch (effect)
		{
		case FREEZE:
			return clamp01(0.34d + 0.42d * coarse + 0.24d * pattern);
			case LOW_PRAYER:
				return clamp01(0.32d + 0.34d * coarse + 0.34d * pattern);
			case DAMAGE:
			case LOW_HEALTH:
				return clamp01(0.38d + 0.42d * coarse + 0.20d * pattern);
			case POISON_TICK:
			case VENOM_TICK:
				return clamp01(0.36d + 0.36d * coarse + 0.28d * pattern);
			default:
				return 0.55d + 0.45d * coarse;
		}
	}

	private static double baseMaterialAmount(
		StatusEffect effect,
		double wash,
		double pattern)
	{
		double boundedWash = clamp01(wash);
		double boundedPattern = clamp01(pattern);
		switch (effect)
		{
			case FREEZE:
				return 0.20d + 0.28d * boundedWash + 0.18d * boundedPattern;
			case LOW_PRAYER:
				return 0.19d + 0.28d * boundedWash + 0.14d * boundedPattern;
			case DAMAGE:
				return 0.16d + 0.24d * boundedWash + 0.27d * boundedPattern;
			case POISON:
				return clamp01(0.62d + 0.28d * boundedWash + 0.10d * boundedPattern);
			case VENOM:
				return clamp01(0.64d + 0.24d * boundedWash + 0.12d * boundedPattern);
			case DISEASE:
				return clamp01(0.60d + 0.30d * boundedWash + 0.10d * boundedPattern);
			case POISON_TICK:
			case VENOM_TICK:
				return 0.18d + 0.26d * boundedWash + 0.22d * boundedPattern;
			case LOW_HEALTH:
				return clamp01(0.80d + 0.16d * boundedWash + 0.04d * boundedPattern);
			default:
				return 0.30d + 0.42d * boundedWash;
		}
	}

	private static double distressMaterialAmount(StatusEffect effect, double pattern)
	{
		double bounded = clamp01(pattern);
		switch (effect)
		{
			case FREEZE:
				return 0.012d + 0.94d * Math.pow(bounded, 0.70d);
			case LOW_PRAYER:
				return 0.015d + 0.90d * Math.pow(bounded, 0.74d);
			case DAMAGE:
				return 0.010d + 0.96d * Math.pow(bounded, 0.72d);
			case POISON:
			case VENOM:
			case DISEASE:
				return clamp01(0.06d + 0.94d * Math.pow(bounded, 0.78d));
			case POISON_TICK:
			case VENOM_TICK:
				return 0.010d + 0.96d * Math.pow(bounded, 0.72d);
			case LOW_HEALTH:
				return clamp01(0.12d + 0.88d * Math.pow(bounded, 0.72d));
			default:
				return 0.035d + 0.78d * Math.pow(bounded, 0.82d);
		}
	}

	private static double baseBrightness(StatusEffect effect, double wash)
	{
		switch (effect)
		{
			case FREEZE:
				return 0.52d + 0.60d * wash;
			case LOW_PRAYER:
				return 0.58d + 0.54d * wash;
			case DAMAGE:
			case LOW_HEALTH:
				return 0.52d + 0.48d * wash;
			default:
				return 0.66d + 0.46d * wash;
		}
	}

	private static double distressBrightness(StatusEffect effect, double pattern)
	{
		switch (effect)
		{
			case FREEZE:
				return 1.02d + 0.58d * pattern;
			case LOW_PRAYER:
				return 0.92d + 0.52d * pattern;
			case VENOM:
			case VENOM_TICK:
				return 0.88d + 0.50d * pattern;
			case DAMAGE:
			case LOW_HEALTH:
				return 0.60d + 0.42d * pattern;
			default:
				return 0.72d + 0.48d * pattern;
		}
	}

	private static boolean isTransient(StatusEffect effect)
	{
		return effect == StatusEffect.DAMAGE
			|| effect == StatusEffect.POISON_TICK
			|| effect == StatusEffect.VENOM_TICK;
	}

	private static boolean contributesStatusTint(StatusEffect effect)
	{
		return !isTransient(effect);
	}

	private static int scaledCell(double size, double scale)
	{
		return Math.max(4, (int) Math.round(size * scale));
	}

	private static double pointToSegmentDistance(
		double x,
		double y,
		double startX,
		double startY,
		double endX,
		double endY)
	{
		double lineX = endX - startX;
		double lineY = endY - startY;
		double lengthSquared = lineX * lineX + lineY * lineY;
		if (lengthSquared <= 0)
		{
			return Math.hypot(x - startX, y - startY);
		}

		double amount = clamp01(((x - startX) * lineX + (y - startY) * lineY) / lengthSquared);
		double nearestX = startX + lineX * amount;
		double nearestY = startY + lineY * amount;
		return Math.hypot(x - nearestX, y - nearestY);
	}

	private void drawFreezeCrystals(
		Graphics2D graphics,
		int width,
		int height,
		double severity,
		double master,
		Color configuredColor)
	{
		Color color = configuredColor == null ? new Color(0, 0, 0, 0) : configuredColor;
		if (severity <= 0 || master <= 0 || color.getAlpha() <= 0)
		{
			clearFreezeDetailFrame();
			return;
		}

		long severityKey = Double.doubleToLongBits(severity);
		long masterKey = Double.doubleToLongBits(master);
		int colorKey = color.getRGB();
		boolean resized = freezeDetailFrame == null
			|| freezeDetailFrame.getWidth() != width
			|| freezeDetailFrame.getHeight() != height;
		if (resized)
		{
			freezeDetailFrame = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB_PRE);
			freezeDetailFrameValid = false;
		}

		if (!freezeDetailFrameValid
			|| freezeDetailSeverity != severityKey
			|| freezeDetailMaster != masterKey
			|| freezeDetailColor != colorKey)
		{
			Arrays.fill(
				((DataBufferInt) freezeDetailFrame.getRaster().getDataBuffer()).getData(),
				0);
			Graphics2D detailGraphics = freezeDetailFrame.createGraphics();
			try
			{
				detailGraphics.setRenderingHint(
					RenderingHints.KEY_ANTIALIASING,
					RenderingHints.VALUE_ANTIALIAS_ON);
				renderFreezeDetails(
					detailGraphics,
					width,
					height,
					severity,
					master,
					color);
			}
			finally
			{
				detailGraphics.dispose();
			}
			freezeDetailSeverity = severityKey;
			freezeDetailMaster = masterKey;
			freezeDetailColor = colorKey;
			freezeDetailFrameValid = true;
			freezeDetailBuildCount++;
		}

		graphics.setComposite(AlphaComposite.SrcOver);
		graphics.drawImage(freezeDetailFrame, 0, 0, null);
	}

	private void renderFreezeDetails(
		Graphics2D graphics,
		int width,
		int height,
		double severity,
		double master,
		Color configuredColor)
	{
		Color color = configuredColor == null ? new Color(0, 0, 0, 0) : configuredColor;
		double colorAlpha = color.getAlpha() / 255.0d;
		if (severity <= 0 || master <= 0 || colorAlpha <= 0)
		{
			return;
		}

		FreezeCrystalSet crystals = getFreezeCrystals(width, height);
		Color bodyColor = mixWithWhite(color, 0.28d);
		Color faceColor = mixWithWhite(color, 0.62d);
		Color ridgeColor = mixWithWhite(color, 0.70d);
		Color rimeColor = mixWithWhite(color, 0.48d);

		for (FreezeFrost frost : crystals.frost)
		{
			double reveal = smoothstepRange(frost.threshold, frost.threshold + 0.20d, severity);
			if (reveal <= 0)
			{
				continue;
			}

			double opacity = clamp01(master * colorAlpha * reveal);
			graphics.setColor(ridgeColor);
			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) (opacity * 0.56d)));
			graphics.setStroke(new BasicStroke(
				(float) Math.max(0.72d, crystals.scale * 1.20d),
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			graphics.draw(frost.trunk);

			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) (opacity * 0.38d)));
			graphics.setStroke(new BasicStroke(
				(float) Math.max(0.55d, crystals.scale * 0.78d),
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			graphics.draw(frost.branches);

			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) (opacity * 0.24d)));
			graphics.setStroke(new BasicStroke(
				(float) Math.max(0.42d, crystals.scale * 0.52d),
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			graphics.draw(frost.twigs);
		}

		for (FreezeCrystal crystal : crystals.crystals)
		{
			double reveal = smoothstepRange(crystal.threshold, crystal.threshold + 0.16d, severity);
			if (reveal <= 0)
			{
				continue;
			}

			double opacity = clamp01(master * colorAlpha * reveal);
			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) (opacity * 0.28d)));
			graphics.setColor(bodyColor);
			graphics.fill(crystal.body);

			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) (opacity * 0.15d)));
			graphics.setColor(faceColor);
			graphics.fill(crystal.face);

			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) (opacity * 0.38d)));
			graphics.setColor(ridgeColor);
			graphics.setStroke(new BasicStroke(
				(float) crystal.strokeWidth,
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_MITER));
			graphics.draw(crystal.ridges);
		}

		double rimeReveal = smoothstepRange(0, 0.38d, severity);
		if (rimeReveal > 0)
		{
			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) clamp01(master * colorAlpha * rimeReveal * 0.16d)));
			graphics.setColor(rimeColor);
			graphics.fill(crystals.rime);
		}
	}

	private void clearFreezeDetailFrame()
	{
		freezeDetailFrame = null;
		freezeDetailFrameValid = false;
		freezeDetailSeverity = 0;
		freezeDetailMaster = 0;
		freezeDetailColor = 0;
	}

	private FreezeCrystalSet getFreezeCrystals(int width, int height)
	{
		if (freezeCrystalSet != null
			&& freezeCrystalSet.width == width
			&& freezeCrystalSet.height == height)
		{
			return freezeCrystalSet;
		}

		double shorter = Math.min(width, height);
		double resolutionScale = shorter / 1080.0d;
		List<FreezeCrystal> crystals = new ArrayList<>();
		List<FreezeFrost> frost = new ArrayList<>();
		Shape rime = buildFreezeRime(width, height, resolutionScale);
		double horizontalSpan = Math.max(0, width - 1.0d);
		double verticalSpan = Math.max(0, height - 1.0d);
		double perimeter = 2.0d * (horizontalSpan + verticalSpan);
		if (perimeter <= 0)
		{
			freezeCrystalSet = new FreezeCrystalSet(
				width,
				height,
				resolutionScale,
				rime,
				frost,
				crystals);
			return freezeCrystalSet;
		}

		int count = Math.max(
			72,
			Math.min(100, (int) Math.round(perimeter / Math.max(1, shorter * 0.070d))));
		double slot = perimeter / count;
		int revealStep = coprimeRevealStep(count);
		double[] frame = new double[7];
		for (int index = 0; index < count; index++)
		{
			double position = slot * (index + 0.5d
				+ (hashUnit(index, 37, 1061) - 0.5d) * 0.42d);
			perimeterFrame(position, horizontalSpan, verticalSpan, frame);
			double rootX = frame[0];
			double rootY = frame[1];
			double inwardAngle = frame[2];
			double inwardX = frame[3];
			double inwardY = frame[4];
			double tangentX = frame[5];
			double tangentY = frame[6];

			Path2D.Double body = new Path2D.Double();
			Path2D.Double face = new Path2D.Double();
			Path2D.Double ridges = new Path2D.Double();
			double centerOffsetX = (width - 1) * 0.5d - rootX;
			double centerOffsetY = (height - 1) * 0.5d - rootY;
			double centerLean = Math.atan2(
				centerOffsetX * tangentX + centerOffsetY * tangentY,
				Math.max(0.000_001d, centerOffsetX * inwardX + centerOffsetY * inwardY));
			double randomLean = (hashUnit(index, 8, 1061) + hashUnit(index, 9, 1061) - 1) * 0.85d;
			double lean = Math.max(
				-0.72d,
				Math.min(
					0.72d,
					0.12d * centerLean + randomLean));
			double angle = inwardAngle + lean;
			double sizeHash = hashUnit(index, 2, 1061);
			double lengthFraction;
			if (sizeHash < 0.35d)
			{
				lengthFraction = interpolate(0.012d, 0.030d, sizeHash / 0.35d);
			}
			else if (sizeHash < 0.80d)
			{
				lengthFraction = interpolate(0.030d, 0.085d, (sizeHash - 0.35d) / 0.45d);
			}
			else
			{
				lengthFraction = interpolate(
					0.085d,
					0.160d,
					Math.pow((sizeHash - 0.80d) / 0.20d, 0.75d));
			}
			double length = shorter * lengthFraction;
			double thicknessRoll = hashUnit(index, 3, 1061);
			double halfWidth = Math.max(
				1.15d * resolutionScale,
				length * (0.040d + 0.040d * thicknessRoll));
			double baseHalf = Math.max(
				1.35d * resolutionScale,
				halfWidth * (0.62d + 0.18d * hashUnit(index, 4, 1061)));
			double directionX = Math.cos(angle);
			double directionY = Math.sin(angle);
			double perpendicularX = -directionY;
			double perpendicularY = directionX;
			double shoulderDistance = Math.max(
				3.0d * resolutionScale,
				length * (0.12d + 0.06d * hashUnit(index, 5, 1061)));
			double lateralInset = halfWidth * Math.abs(
				perpendicularX * inwardX + perpendicularY * inwardY);
			double burial = shoulderDistance + lateralInset + 3.0d * resolutionScale;
			double buriedRootX = rootX - inwardX * burial;
			double buriedRootY = rootY - inwardY * burial;
			double setback = Math.max(
				5.0d * resolutionScale,
				Math.min(
					12.0d * resolutionScale,
					0.10d * length + 1.25d * baseHalf));
			double baseCenterX = buriedRootX - inwardX * setback;
			double baseCenterY = buriedRootY - inwardY * setback;
			double shoulderX = buriedRootX
				+ directionX * shoulderDistance
				+ inwardX * 1.5d * resolutionScale;
			double shoulderY = buriedRootY
				+ directionY * shoulderDistance
				+ inwardY * 1.5d * resolutionScale;
			double tipX = buriedRootX + directionX * length;
			double tipY = buriedRootY + directionY * length;
			double leftX = shoulderX + perpendicularX * halfWidth;
			double leftY = shoulderY + perpendicularY * halfWidth;
			double rightX = shoulderX - perpendicularX * halfWidth * 0.78d;
			double rightY = shoulderY - perpendicularY * halfWidth * 0.78d;
			double baseLeftX = baseCenterX + tangentX * baseHalf;
			double baseLeftY = baseCenterY + tangentY * baseHalf;
			double baseRightX = baseCenterX - tangentX * baseHalf;
			double baseRightY = baseCenterY - tangentY * baseHalf;

			body.moveTo(baseLeftX, baseLeftY);
			body.lineTo(leftX, leftY);
			body.lineTo(tipX, tipY);
			body.lineTo(rightX, rightY);
			body.lineTo(baseRightX, baseRightY);
			body.closePath();

			face.moveTo(baseLeftX, baseLeftY);
			face.lineTo(leftX, leftY);
			face.lineTo(tipX, tipY);
			face.lineTo(baseCenterX, baseCenterY);
			face.closePath();

			ridges.moveTo(leftX, leftY);
			ridges.lineTo(tipX, tipY);
			ridges.lineTo(rightX, rightY);

			int revealRank = (index * revealStep + count / 3) % count;
			double threshold = 0.03d + 0.69d * revealRank / Math.max(1, count - 1.0d);
			crystals.add(new FreezeCrystal(
				body,
				face,
				ridges,
				Math.max(1.20d * resolutionScale, shorter * 0.0012d),
				threshold));
		}

		int frostCount = Math.max(
			24,
			Math.min(38, (int) Math.round(perimeter / Math.max(1, shorter * 0.17d))));
		double frostSlot = perimeter / frostCount;
		int frostRevealStep = coprimeRevealStep(frostCount);
		for (int index = 0; index < frostCount; index++)
		{
			double position = frostSlot * (index + 0.23d
				+ (hashUnit(index, 47, 1171) - 0.5d) * 0.46d);
			perimeterFrame(position, horizontalSpan, verticalSpan, frame);
			double rootX = frame[0];
			double rootY = frame[1];
			double inwardAngle = frame[2];
			double inwardX = frame[3];
			double inwardY = frame[4];
			double tangentX = frame[5];
			double tangentY = frame[6];
			double centerOffsetX = (width - 1) * 0.5d - rootX;
			double centerOffsetY = (height - 1) * 0.5d - rootY;
			double centerLean = Math.atan2(
				centerOffsetX * tangentX + centerOffsetY * tangentY,
				Math.max(0.000_001d, centerOffsetX * inwardX + centerOffsetY * inwardY));
			double randomLean = (hashUnit(index, 13, 1171) + hashUnit(index, 17, 1171) - 1) * 0.62d;
			double currentAngle = inwardAngle + Math.max(
				-0.72d,
				Math.min(0.72d, 0.10d * centerLean + randomLean));
			double trunkLength = shorter
				* (0.035d + 0.070d * Math.pow(hashUnit(index, 19, 1171), 0.80d));
			int segmentCount = 5 + (int) Math.floor(hashUnit(index, 23, 1171) * 4);
			double stepLength = trunkLength / segmentCount;
			double currentX = rootX - inwardX * 12.0d * resolutionScale;
			double currentY = rootY - inwardY * 12.0d * resolutionScale;
			Path2D.Double trunk = new Path2D.Double();
			Path2D.Double branches = new Path2D.Double();
			Path2D.Double twigs = new Path2D.Double();
			trunk.moveTo(currentX, currentY);
			for (int segment = 1; segment <= segmentCount; segment++)
			{
				currentAngle += (hashUnit(index, segment, 1201) - 0.5d) * 0.10d;
				double segmentLength = stepLength
					* (0.85d + 0.30d * hashUnit(index, segment, 1213));
				currentX += Math.cos(currentAngle) * segmentLength;
				currentY += Math.sin(currentAngle) * segmentLength;
				trunk.lineTo(currentX, currentY);
				if (segment >= segmentCount - 1)
				{
					continue;
				}

				double remaining = trunkLength * (1 - segment / (double) segmentCount);
				for (int side = 0; side < 2; side++)
				{
					double branchChance = side == 0 ? 0.68d : 0.58d;
					if (hashUnit(index, segment * 2 + side, 1223) >= branchChance)
					{
						continue;
					}

					double sideSign = side == 0 ? -1 : 1;
					double branchAngle = currentAngle + sideSign
						* (0.56d + 0.45d * hashUnit(index, segment * 2 + side, 1237));
					double branchLength = remaining
						* (0.20d + 0.22d * hashUnit(index, segment * 2 + side, 1249));
					double split = 0.55d
						+ 0.17d * hashUnit(index, segment * 2 + side, 1259);
					double branchMidX = currentX + Math.cos(branchAngle) * branchLength * split;
					double branchMidY = currentY + Math.sin(branchAngle) * branchLength * split;
					double branchEndAngle = branchAngle
						+ (hashUnit(index, segment * 2 + side, 1277) - 0.5d) * 0.12d;
					double branchEndX = branchMidX
						+ Math.cos(branchEndAngle) * branchLength * (1 - split);
					double branchEndY = branchMidY
						+ Math.sin(branchEndAngle) * branchLength * (1 - split);
					branches.moveTo(currentX, currentY);
					branches.lineTo(branchMidX, branchMidY);
					branches.lineTo(branchEndX, branchEndY);

					if (branchLength > 5.0d * resolutionScale
						&& hashUnit(index, segment * 2 + side, 1289) < 0.30d)
					{
						double twigAngle = branchAngle + sideSign
							* (0.44d + 0.34d * hashUnit(index, segment * 2 + side, 1297));
						double twigLength = branchLength
							* (0.25d + 0.20d * hashUnit(index, segment * 2 + side, 1301));
						twigs.moveTo(branchMidX, branchMidY);
						twigs.lineTo(
							branchMidX + Math.cos(twigAngle) * twigLength,
							branchMidY + Math.sin(twigAngle) * twigLength);
					}
				}
			}

			int revealRank = (index * frostRevealStep + frostCount / 4) % frostCount;
			double threshold = 0.02d
				+ 0.56d * revealRank / Math.max(1, frostCount - 1.0d);
			frost.add(new FreezeFrost(trunk, branches, twigs, threshold));
		}

		freezeCrystalSet = new FreezeCrystalSet(
			width,
			height,
			resolutionScale,
			rime,
			frost,
			crystals);
		return freezeCrystalSet;
	}

	private static Shape buildFreezeRime(int width, int height, double scale)
	{
		double horizontalSpan = Math.max(0, width - 1.0d);
		double verticalSpan = Math.max(0, height - 1.0d);
		double outside = Math.max(1, 6.0d * scale);
		double step = Math.max(3, 18.0d * scale);
		Path2D.Double rime = new Path2D.Double(Path2D.WIND_NON_ZERO);

		rime.moveTo(-outside, -outside);
		rime.lineTo(horizontalSpan + outside, -outside);
		for (double x = horizontalSpan; x > 0; x -= step)
		{
			rime.lineTo(x, freezeRimeDepth(x, scale, 0));
		}
		rime.lineTo(0, freezeRimeDepth(0, scale, 0));
		rime.closePath();

		rime.moveTo(-outside, verticalSpan + outside);
		rime.lineTo(horizontalSpan + outside, verticalSpan + outside);
		for (double x = horizontalSpan; x > 0; x -= step)
		{
			rime.lineTo(x, verticalSpan - freezeRimeDepth(x, scale, 2));
		}
		rime.lineTo(0, verticalSpan - freezeRimeDepth(0, scale, 2));
		rime.closePath();

		rime.moveTo(-outside, -outside);
		rime.lineTo(-outside, verticalSpan + outside);
		for (double y = verticalSpan; y > 0; y -= step)
		{
			rime.lineTo(freezeRimeDepth(y, scale, 3), y);
		}
		rime.lineTo(freezeRimeDepth(0, scale, 3), 0);
		rime.closePath();

		rime.moveTo(horizontalSpan + outside, -outside);
		rime.lineTo(horizontalSpan + outside, verticalSpan + outside);
		for (double y = verticalSpan; y > 0; y -= step)
		{
			rime.lineTo(horizontalSpan - freezeRimeDepth(y, scale, 1), y);
		}
		rime.lineTo(horizontalSpan - freezeRimeDepth(0, scale, 1), 0);
		rime.closePath();
		return rime;
	}

	private static double freezeRimeDepth(double coordinate, double scale, int side)
	{
		double boundedScale = Math.max(0.001d, scale);
		double cellSize = Math.max(1, 72.0d * boundedScale);
		int cell = (int) Math.floor(coordinate / cellSize);
		double fraction = coordinate / cellSize - cell;
		double noise = interpolate(
			hashUnit(cell, side, 1321),
			hashUnit(cell + 1, side, 1321),
			smootherstep(fraction));
		int sample = (int) Math.floor(coordinate / Math.max(1, 18.0d * boundedScale));
		double tongueRoll = hashUnit(sample, side, 1331);
		double tongue = tongueRoll > 0.84d
			? boundedScale * (8 + 10 * hashUnit(sample, side, 1361))
			: 0;
		return boundedScale * (3 + 7 * noise) + tongue;
	}

	private static void perimeterFrame(
		double position,
		double horizontalSpan,
		double verticalSpan,
		double[] frame)
	{
		if (position < horizontalSpan)
		{
			frame[0] = position;
			frame[1] = 0;
			frame[2] = Math.PI * 0.5d;
			frame[3] = 0;
			frame[4] = 1;
			frame[5] = 1;
			frame[6] = 0;
		}
		else if (position < horizontalSpan + verticalSpan)
		{
			frame[0] = horizontalSpan;
			frame[1] = position - horizontalSpan;
			frame[2] = Math.PI;
			frame[3] = -1;
			frame[4] = 0;
			frame[5] = 0;
			frame[6] = 1;
		}
		else if (position < horizontalSpan * 2.0d + verticalSpan)
		{
			frame[0] = horizontalSpan - (position - horizontalSpan - verticalSpan);
			frame[1] = verticalSpan;
			frame[2] = -Math.PI * 0.5d;
			frame[3] = 0;
			frame[4] = -1;
			frame[5] = -1;
			frame[6] = 0;
		}
		else
		{
			frame[0] = 0;
			frame[1] = verticalSpan - (position - horizontalSpan * 2.0d - verticalSpan);
			frame[2] = 0;
			frame[3] = 1;
			frame[4] = 0;
			frame[5] = 0;
			frame[6] = -1;
		}
	}

	private static int coprimeRevealStep(int count)
	{
		int candidate = Math.max(2, (int) Math.round(count * 0.618_033_988_75d));
		while (greatestCommonDivisor(candidate, count) != 1)
		{
			candidate++;
			if (candidate >= count)
			{
				candidate = 2;
			}
		}
		return candidate;
	}

	private static int greatestCommonDivisor(int first, int second)
	{
		int left = Math.abs(first);
		int right = Math.abs(second);
		while (right != 0)
		{
			int remainder = left % right;
			left = right;
			right = remainder;
		}
		return left;
	}

	private void drawPrayerSymbols(
		Graphics2D graphics,
		int width,
		int height,
		double severity,
		double master,
		double motion,
		double gameTicks,
		Color configuredColor)
	{
		Color color = configuredColor == null ? new Color(0, 0, 0, 0) : configuredColor;
		double colorAlpha = color.getAlpha() / 255.0d;
		if (severity <= 0 || master <= 0 || colorAlpha <= 0)
		{
			return;
		}

		PrayerSymbolSet symbols = getPrayerSymbols(width, height);
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue()));
		for (PrayerSymbol symbol : symbols.symbols)
		{
			double reveal = smoothstepRange(symbol.threshold, symbol.threshold + 0.18d, severity);
			if (reveal <= 0)
			{
				continue;
			}

			double speed = prayerMotionSpeed(motion);
			double cycle = positiveFraction(
				(symbol.phaseTicks + gameTicks * speed) / symbol.durationTicks);
			double fade = prayerFade(cycle);
			if (fade <= 0)
			{
				continue;
			}

			AffineTransform fall = AffineTransform.getTranslateInstance(
				0,
				symbol.fallDistance * prayerTravel(cycle));
			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) clamp01(master * colorAlpha * reveal * fade)));
			graphics.fill(fall.createTransformedShape(symbol.cross));
		}
	}

	private PrayerSymbolSet getPrayerSymbols(int width, int height)
	{
		if (prayerSymbolSet != null && prayerSymbolSet.width == width && prayerSymbolSet.height == height)
		{
			return prayerSymbolSet;
		}

		double shorter = Math.min(width, height);
		List<PrayerSymbol> symbols = new ArrayList<>();
		int count = 18;
		int revealStep = coprimeRevealStep(count);
		for (int index = 0; index < count; index++)
		{
			boolean sideLane = index >= 12;
			double x;
			double y;
			double fallDistance;
			if (sideLane)
			{
				boolean right = index % 2 == 0;
				x = width * (right
					? 0.91d + 0.07d * hashUnit(index, 0, 719)
					: 0.02d + 0.07d * hashUnit(index, 0, 719));
				y = height * (-0.08d + 0.88d * hashUnit(index, 1, 719));
				fallDistance = height * (0.14d + 0.20d * hashUnit(index, 2, 719));
			}
			else
			{
				x = width * (0.04d + 0.92d * hashUnit(index, 0, 719));
				y = -shorter * (0.010d + 0.040d * hashUnit(index, 1, 719));
				fallDistance = height * (0.13d + 0.16d * hashUnit(index, 2, 719));
			}
			double size = shorter * (0.008d + 0.007d * hashUnit(index, 3, 719));
			double rotation = (hashUnit(index, 6, 719) - 0.5d) * Math.PI * 0.045d;
			Path2D.Double cross = new Path2D.Double();
			double waist = size * 0.32d;
			cross.moveTo(x, y - size);
			cross.lineTo(x + waist, y - waist);
			cross.lineTo(x + size, y);
			cross.lineTo(x + waist, y + waist);
			cross.lineTo(x, y + size);
			cross.lineTo(x - waist, y + waist);
			cross.lineTo(x - size, y);
			cross.lineTo(x - waist, y - waist);
			cross.closePath();
			AffineTransform rotate = AffineTransform.getRotateInstance(rotation, x, y);
			Shape rotatedCross = rotate.createTransformedShape(cross);
			int revealRank = (index * revealStep + count / 3) % count;
			double floor = PlayerStatus.VISIBLE_DANGER_FLOOR;
			double threshold = floor
				+ (0.74d - floor) * revealRank / (count - 1.0d);
			double durationTicks = 8 + 10 * hashUnit(index, 4, 719);
			symbols.add(new PrayerSymbol(
				rotatedCross,
				fallDistance,
				durationTicks,
				durationTicks * hashUnit(index, 5, 719),
				threshold));
		}
		prayerSymbolSet = new PrayerSymbolSet(width, height, symbols);
		return prayerSymbolSet;
	}

	private void drawBloodDecals(
		Graphics2D graphics,
		int width,
		int height,
		double rawHealthSeverity,
		double master,
		int amount,
		Color configuredColor)
	{
		Color color = configuredColor == null ? new Color(0, 0, 0, 0) : configuredColor;
		double colorAlpha = color.getAlpha() / 255.0d;
		double healthProgress = dangerProgress(rawHealthSeverity);
		if (healthProgress <= 0 || master <= 0 || colorAlpha <= 0 || amount <= 0)
		{
			return;
		}

		BloodDecalSet decals = getBloodDecals(width, height);
		Color core = new Color(color.getRed(), color.getGreen(), color.getBlue());
		double coverage = boundedPercent(amount) / 100.0d;
		double amountAlpha = 0.10d + 0.90d * square(coverage);
		for (BloodDecal decal : decals.decals)
		{
			double healthReveal = smoothstepRange(
				decal.healthThreshold,
				decal.healthThreshold + 0.14d,
				healthProgress);
			double coverageReveal = smoothstepRange(
				decal.coverageThreshold,
				Math.min(1, decal.coverageThreshold + 0.10d),
				coverage);
			double reveal = healthReveal * coverageReveal;
			if (reveal <= 0)
			{
				continue;
			}
			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) clamp01(master * colorAlpha * amountAlpha * reveal)));
			graphics.setColor(core);
			graphics.fill(decal.body);
			for (Shape drip : decal.drips)
			{
				graphics.fill(drip);
			}
			graphics.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER,
				(float) clamp01(master * colorAlpha * amountAlpha * reveal * 0.72d)));
			for (Shape droplet : decal.droplets)
			{
				graphics.fill(droplet);
			}
		}
	}

	private BloodDecalSet getBloodDecals(int width, int height)
	{
		if (bloodDecalSet != null && bloodDecalSet.width == width
			&& bloodDecalSet.height == height)
		{
			return bloodDecalSet;
		}

		double centerX = (width - 1) * 0.5d;
		double centerY = (height - 1) * 0.5d;
		double shorter = Math.min(width, height);
		int count = 24;
		List<BloodDecal> decals = new ArrayList<>();
		for (int index = 0; index < count; index++)
		{
			double angle = Math.PI * 2 * positiveFraction(
				index * 0.618_033_988_75d + 0.08d * hashUnit(index, 0, 941));
			double ring = 0.74d + 0.24d * hashUnit(index, 1, 941);
			double x = centerX + Math.cos(angle) * centerX * ring;
			double y = centerY + Math.sin(angle) * centerY * ring;
			double sizeRoll = hashUnit(index, 2, 941);
			double radiusFraction = sizeRoll > 0.88d
				? 0.010d + 0.005d * hashUnit(index, 12, 941)
				: sizeRoll > 0.52d
					? 0.006d + 0.005d * hashUnit(index, 12, 941)
					: 0.0028d + 0.0038d * hashUnit(index, 12, 941);
			double radius = shorter * radiusFraction;
			double anisotropy = 0.50d + 0.42d * hashUnit(index, 3, 941);
			double rotation = hashUnit(index, 4, 941) * Math.PI * 2;
			Path2D.Double body = new Path2D.Double();
			int samples = 24;
			for (int sample = 0; sample < samples; sample++)
			{
				double localAngle = Math.PI * 2 * sample / samples;
				double irregularRadius = radius * (1
					+ 0.20d * Math.sin(localAngle * 3 + hashUnit(index, 5, 941) * Math.PI * 2)
					+ 0.13d * Math.sin(localAngle * 7 + hashUnit(index, 6, 941) * Math.PI * 2)
					+ 0.07d * (hashUnit(index, sample, 947) - 0.5d));
				double localX = Math.cos(localAngle) * irregularRadius;
				double localY = Math.sin(localAngle) * irregularRadius * anisotropy;
				double pointX = x + localX * Math.cos(rotation) - localY * Math.sin(rotation);
				double pointY = y + localX * Math.sin(rotation) + localY * Math.cos(rotation);
				if (sample == 0)
				{
					body.moveTo(pointX, pointY);
				}
				else
				{
					body.lineTo(pointX, pointY);
				}
			}
			body.closePath();

			List<Shape> droplets = new ArrayList<>();
			int dropletCount = 2 + (int) Math.floor(hashUnit(index, 7, 941) * 4);
			for (int drop = 0; drop < dropletCount; drop++)
			{
				double dropAngle = hashUnit(index, drop, 953) * Math.PI * 2;
				double distance = radius * (1.25d + 2.15d * hashUnit(index, drop, 967));
				double dropRadius = radius * (0.10d + 0.14d * hashUnit(index, drop, 971));
				double dropX = x + Math.cos(dropAngle) * distance;
				double dropY = y + Math.sin(dropAngle) * distance;
				droplets.add(new Ellipse2D.Double(
					dropX - dropRadius,
					dropY - dropRadius * 0.76d,
					dropRadius * 2,
					dropRadius * 1.52d));
			}

			List<Shape> drips = new ArrayList<>();
			int dripCount = sizeRoll > 0.84d && hashUnit(index, 8, 941) > 0.55d ? 1 : 0;
			for (int drip = 0; drip < dripCount; drip++)
			{
				double dripWidth = radius * (0.12d + 0.10d * hashUnit(index, drip, 977));
				double dripHeight = radius * (0.70d + 1.90d * hashUnit(index, drip, 983));
				double dripX = x + (hashUnit(index, drip, 991) - 0.5d) * radius - dripWidth * 0.5d;
				double dripY = y + radius * anisotropy * 0.34d;
				drips.add(new RoundRectangle2D.Double(
					dripX,
					dripY,
					dripWidth,
					dripHeight,
					dripWidth,
					dripWidth));
			}

			int healthRank = index * 11 % count;
			int coverageRank = index * 7 % count;
			double healthThreshold = 0.03d
				+ 0.77d * healthRank / (count - 1.0d);
			double coverageThreshold = 0.90d * coverageRank / (count - 1.0d);
			decals.add(new BloodDecal(
				body,
				droplets,
				drips,
				healthThreshold,
				coverageThreshold));
		}
		bloodDecalSet = new BloodDecalSet(width, height, decals);
		return bloodDecalSet;
	}

	private BufferedImage prepareSampledFrame(
		int canvasWidth,
		int canvasHeight)
	{
		int width = Math.max(1, (canvasWidth + SAMPLE_STEP - 1) / SAMPLE_STEP);
		int height = Math.max(1, (canvasHeight + SAMPLE_STEP - 1) / SAMPLE_STEP);
		if (sampledFrame == null || sampledFrame.getWidth() != width || sampledFrame.getHeight() != height)
		{
			if (sampledFrameGraphics != null)
			{
				sampledFrameGraphics.dispose();
			}
			sampledFrame = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB_PRE);
			sampledFrameGraphics = sampledFrame.createGraphics();
			sampledFrameGraphics.setRenderingHint(
				RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			sampledFrameGraphics.setRenderingHint(
				RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			invalidateStableComposition();
		}
		return sampledFrame;
	}

	private static boolean isSampledCompositionTimeStable(
		ContourTexture[] textures,
		double motion,
		boolean healthPulseEnabled)
	{
		for (int i = 0; i < RENDER_ORDER.length; i++)
		{
			if (textures[i] == null)
			{
				continue;
			}
			StatusEffect effect = RENDER_ORDER[i];
			if (isTransient(effect)
				|| (effect == StatusEffect.LOW_HEALTH && healthPulseEnabled)
				|| (motion > 0 && effect != StatusEffect.FREEZE))
			{
				return false;
			}
		}
		return true;
	}

	private boolean matchesSampledComposition(
		int canvasWidth,
		int canvasHeight,
		int band,
		int feather,
		double tintOpacity,
		int tintColor,
		double flashOpacity,
		int flashColor,
		double[] severity,
		double[] baseOpacity,
		double[] distressOpacity,
		Color[] colors,
		double master)
	{
		if (!sampledCompositionValid
			|| composedCanvasWidth != canvasWidth
			|| composedCanvasHeight != canvasHeight
			|| composedBand != band
			|| composedFeather != boundedPercent(feather)
			|| composedTintOpacity != Float.floatToIntBits((float) tintOpacity)
			|| composedTintColor != tintColor
			|| composedFlashOpacity != Float.floatToIntBits((float) flashOpacity)
			|| composedFlashColor != flashColor)
		{
			return false;
		}

		for (int i = 0; i < RENDER_ORDER.length; i++)
		{
			int color = colors[i] == null ? 0 : colors[i].getRGB();
			if (composedColors[i] != color
				|| composedSeverity[i] != Double.doubleToLongBits(severity[i])
				|| composedBaseOpacity[i] != Float.floatToIntBits((float) (baseOpacity[i] * master))
				|| composedDistressOpacity[i] != Float.floatToIntBits((float) (distressOpacity[i] * master)))
			{
				return false;
			}
		}
		return true;
	}

	private void rememberSampledComposition(
		int canvasWidth,
		int canvasHeight,
		int band,
		int feather,
		double tintOpacity,
		int tintColor,
		double flashOpacity,
		int flashColor,
		double[] severity,
		double[] baseOpacity,
		double[] distressOpacity,
		Color[] colors,
		double master)
	{
		composedCanvasWidth = canvasWidth;
		composedCanvasHeight = canvasHeight;
		composedBand = band;
		composedFeather = boundedPercent(feather);
		composedTintOpacity = Float.floatToIntBits((float) tintOpacity);
		composedTintColor = tintColor;
		composedFlashOpacity = Float.floatToIntBits((float) flashOpacity);
		composedFlashColor = flashColor;
		for (int i = 0; i < RENDER_ORDER.length; i++)
		{
			composedColors[i] = colors[i] == null ? 0 : colors[i].getRGB();
			composedSeverity[i] = Double.doubleToLongBits(severity[i]);
			composedBaseOpacity[i] = Float.floatToIntBits((float) (baseOpacity[i] * master));
			composedDistressOpacity[i] = Float.floatToIntBits((float) (distressOpacity[i] * master));
		}
		sampledCompositionValid = true;
		stableUpscaledFrameValid = false;
	}

	private BufferedImage prepareUpscaledFrame(
		BufferedImage frame,
		int canvasWidth,
		int canvasHeight,
		boolean reuseStableFrame)
	{
		if (stableUpscaledFrame == null
			|| stableUpscaledFrame.getWidth() != canvasWidth
			|| stableUpscaledFrame.getHeight() != canvasHeight)
		{
			stableUpscaledFrame = new BufferedImage(
				canvasWidth,
				canvasHeight,
				BufferedImage.TYPE_INT_ARGB_PRE);
			stableUpscaledFrameValid = false;
		}

		if (!reuseStableFrame || !stableUpscaledFrameValid)
		{
			upscalePremultiplied(frame, stableUpscaledFrame);
			stableUpscaledFrameValid = reuseStableFrame;
			if (reuseStableFrame)
			{
				stableUpscaleBuildCount++;
			}
		}
		return stableUpscaledFrame;
	}

	void upscalePremultiplied(BufferedImage source, BufferedImage target)
	{
		int sourceWidth = source.getWidth();
		int sourceHeight = source.getHeight();
		int targetWidth = target.getWidth();
		int targetHeight = target.getHeight();
		ensureUpscaleMaps(sourceWidth, sourceHeight, targetWidth, targetHeight);

		int[] sourcePixels = ((DataBufferInt) source.getRaster().getDataBuffer()).getData();
		int[] targetPixels = ((DataBufferInt) target.getRaster().getDataBuffer()).getData();
		for (int sourceY = 0; sourceY < sourceHeight; sourceY++)
		{
			int sourceOffset = sourceY * sourceWidth;
			int horizontalOffset = sourceY * targetWidth;
			for (int targetX = 0; targetX < targetWidth; targetX++)
			{
				horizontalUpscalePixels[horizontalOffset + targetX] = lerpPremultiplied(
					sourcePixels[sourceOffset + upscaleXLow[targetX]],
					sourcePixels[sourceOffset + upscaleXHigh[targetX]],
					upscaleXWeight[targetX]);
			}
		}

		for (int targetY = 0; targetY < targetHeight; targetY++)
		{
			int targetOffset = targetY * targetWidth;
			int lowOffset = upscaleYLow[targetY] * targetWidth;
			int weight = upscaleYWeight[targetY];
			if (weight == 0)
			{
				System.arraycopy(
					horizontalUpscalePixels,
					lowOffset,
					targetPixels,
					targetOffset,
					targetWidth);
				continue;
			}

			int highOffset = upscaleYHigh[targetY] * targetWidth;
			for (int targetX = 0; targetX < targetWidth; targetX++)
			{
				targetPixels[targetOffset + targetX] = lerpPremultiplied(
					horizontalUpscalePixels[lowOffset + targetX],
					horizontalUpscalePixels[highOffset + targetX],
					weight);
			}
		}
	}

	private void ensureUpscaleMaps(
		int sourceWidth,
		int sourceHeight,
		int targetWidth,
		int targetHeight)
	{
		if (upscaleSourceWidth == sourceWidth
			&& upscaleSourceHeight == sourceHeight
			&& upscaleTargetWidth == targetWidth
			&& upscaleTargetHeight == targetHeight)
		{
			return;
		}

		upscaleSourceWidth = sourceWidth;
		upscaleSourceHeight = sourceHeight;
		upscaleTargetWidth = targetWidth;
		upscaleTargetHeight = targetHeight;
		horizontalUpscalePixels = new int[targetWidth * sourceHeight];
		upscaleXLow = new int[targetWidth];
		upscaleXHigh = new int[targetWidth];
		upscaleXWeight = new int[targetWidth];
		upscaleYLow = new int[targetHeight];
		upscaleYHigh = new int[targetHeight];
		upscaleYWeight = new int[targetHeight];
		buildUpscaleAxis(sourceWidth, targetWidth, upscaleXLow, upscaleXHigh, upscaleXWeight);
		buildUpscaleAxis(sourceHeight, targetHeight, upscaleYLow, upscaleYHigh, upscaleYWeight);
	}

	private static void buildUpscaleAxis(
		int sourceSize,
		int targetSize,
		int[] low,
		int[] high,
		int[] weight)
	{
		for (int target = 0; target < targetSize; target++)
		{
			double sourcePosition = (target + 0.5d) * sourceSize / targetSize - 0.5d;
			int lower = (int) Math.floor(sourcePosition);
			double fraction = sourcePosition - lower;
			if (lower < 0)
			{
				lower = 0;
				fraction = 0;
			}
			int upper = lower + 1;
			if (upper >= sourceSize)
			{
				upper = sourceSize - 1;
				lower = upper;
				fraction = 0;
			}
			low[target] = lower;
			high[target] = upper;
			weight[target] = Math.max(0, Math.min(256, (int) Math.round(fraction * 256)));
		}
	}

	private static int lerpPremultiplied(int first, int second, int weight)
	{
		if (weight <= 0 || first == second)
		{
			return first;
		}
		if (weight >= 256)
		{
			return second;
		}

		int inverse = 256 - weight;
		long redBlue = (first & 0x00ff00ffL) * inverse
			+ (second & 0x00ff00ffL) * weight
			+ 0x00800080L;
		long alphaGreen = ((first >>> 8) & 0x00ff00ffL) * inverse
			+ ((second >>> 8) & 0x00ff00ffL) * weight
			+ 0x00800080L;
		return (int) ((redBlue >>> 8) & 0x00ff00ffL)
			| (int) (((alphaGreen >>> 8) & 0x00ff00ffL) << 8);
	}

	private void invalidateStableComposition()
	{
		sampledCompositionValid = false;
		stableUpscaledFrameValid = false;
	}

	static AffineTransform toSampledTransform(
		AffineTransform canvasTransform,
		int canvasWidth,
		int canvasHeight,
		int sampledWidth,
		int sampledHeight)
	{
		if (canvasTransform == null || canvasWidth <= 0 || canvasHeight <= 0
			|| sampledWidth <= 0 || sampledHeight <= 0)
		{
			return new AffineTransform();
		}

		double scaleX = canvasWidth / (double) sampledWidth;
		double scaleY = canvasHeight / (double) sampledHeight;
		double[] matrix = new double[6];
		canvasTransform.getMatrix(matrix);
		return new AffineTransform(
			matrix[0],
			matrix[1] * scaleX / scaleY,
			matrix[2] * scaleY / scaleX,
			matrix[3],
			matrix[4] / scaleX,
			matrix[5] / scaleY);
	}

	private static AffineTransform distressTransform(
		StatusEffect effect,
		int width,
		int height,
		double seconds,
		double severity,
		double motion)
	{
		double boundedSeverity = clamp01(severity);
		if (isTransient(effect))
		{
			double impactScale = 1 + 0.032d * boundedSeverity;
			AffineTransform impact = new AffineTransform();
			impact.translate(width / 2.0d, height / 2.0d);
			impact.scale(impactScale, impactScale);
			impact.translate(-width / 2.0d, -height / 2.0d);
			return impact;
		}

		double boundedMotion = clamp01(motion);
		if (boundedMotion == 0 || effect == StatusEffect.FREEZE)
		{
			return null;
		}

		double speed = motionSpeed(effect);
		double wave = 0.5d + 0.5d * Math.sin(seconds * speed + effect.getSeed());
		double driftWave = Math.sin(seconds * speed * 0.61d + effect.getSeed() * 0.37d);
		double motionScale = materialScale(width, height);
		double movementScale = effect == StatusEffect.LOW_PRAYER ? 0.72d : 1.0d;
		double drift = 14.0d * motionScale * boundedMotion * boundedSeverity * movementScale;
		double translateX = driftWave * drift;
		double translateY = Math.cos(seconds * speed * 0.47d + effect.getSeed()) * drift * 0.72d;
		double scale = 1 + boundedMotion * boundedSeverity * (0.025d + 0.055d * wave);
		double rotation = Math.sin(seconds * speed * 0.33d + effect.getSeed())
			* 0.012d
			* boundedMotion
			* boundedSeverity
			* movementScale;
		AffineTransform transform = new AffineTransform();
		transform.translate(width / 2.0d + translateX, height / 2.0d + translateY);
		transform.rotate(rotation);
		transform.scale(scale, scale);
		transform.translate(-width / 2.0d, -height / 2.0d);
		return transform;
	}

	static double severityResponse(double severity, int escalationPercent)
	{
		double bounded = clamp01(severity);
		double amount = boundedPercent(escalationPercent) / 100.0d;
		double floor = PlayerStatus.VISIBLE_DANGER_FLOOR;
		if (bounded <= floor || amount <= 0)
		{
			return bounded;
		}

		double progress = (bounded - floor) / (1 - floor);
		double contrasted = smoothstep(progress);
		return floor + (1 - floor) * interpolate(progress, contrasted, amount);
	}

	static double lowHealthSeverityResponse(double severity, int escalationPercent)
	{
		double bounded = clamp01(severity);
		double floor = PlayerStatus.VISIBLE_DANGER_FLOOR;
		if (bounded < floor)
		{
			return bounded;
		}

		double progress = (bounded - floor) / (1 - floor);
		double onset = lowHealthOnsetResponse(progress);
		double steadyPresence = interpolate(
			LOW_HEALTH_EDGE_ONSET,
			0.56d + 0.16d * progress,
			onset);
		double escalation = boundedPercent(escalationPercent) / 100.0d;
		double criticalStart = interpolate(0.84d, 0.72d, escalation);
		double criticalRamp = smootherstep(
			(progress - criticalStart) / (1 - criticalStart));
		return clamp01(steadyPresence + (1 - steadyPresence) * criticalRamp);
	}

	static double distressResponse(double severity)
	{
		return smoothstepRange(0.24d, 1.0d, clamp01(severity));
	}

	static double activeBaseResponse(double severity)
	{
		double bounded = clamp01(severity);
		return bounded <= 0 ? 0 : 0.07d + 0.93d * bounded;
	}

	static double lowHealthBaseResponse(double severity)
	{
		double bounded = clamp01(severity);
		return bounded <= 0
			? 0
			: 0.82d * bounded + 0.18d * smootherstep(bounded / 0.24d);
	}

	static double tintResponse(double severity, int tintPercent)
	{
		double maximum = boundedPercent(tintPercent) / 100.0d;
		return maximum * smoothstepRange(0.35d, 1.0d, clamp01(severity));
	}

	static double lowHealthTintResponse(
		double rawSeverity,
		int tintPercent,
		double masterIntensity)
	{
		double maximum = boundedPercent(tintPercent) / 100.0d;
		double master = clamp01(masterIntensity);
		double boundedSeverity = clamp01(rawSeverity);
		if (maximum <= 0 || master <= 0 || boundedSeverity <= 0)
		{
			return 0;
		}

		double progress = dangerProgress(boundedSeverity);
		double onset = lowHealthOnsetResponse(progress);
		double steady = interpolate(
			LOW_HEALTH_TINT_ONSET,
			0.18d + 0.50d * Math.sqrt(progress),
			onset);
		double terminal = 0.32d * smootherstep((progress - 0.78d) / 0.22d);
		double healthScale = clamp01(steady + terminal);
		return maximum * healthScale * Math.sqrt(master);
	}

	private static double lowHealthOnsetResponse(double progress)
	{
		return smootherstep(clamp01(progress) / LOW_HEALTH_ONSET_PROGRESS);
	}

	static double prayerMotionSpeed(double motion)
	{
		return 0.60d + 1.40d * clamp01(motion);
	}

	static double prayerTravel(double cycle)
	{
		return 0.18d + 0.82d * clamp01(cycle);
	}

	static double prayerFade(double cycle)
	{
		double bounded = clamp01(cycle);
		return smoothstepRange(0, 0.10d, bounded)
			* (1 - smoothstepRange(0.68d, 1.0d, bounded));
	}

	static double contourWeight(double depth, double reach, int featherPercent)
	{
		if (!Double.isFinite(depth) || !Double.isFinite(reach) || reach <= 0 || depth >= reach)
		{
			return 0;
		}
		if (depth <= 0)
		{
			return 1;
		}

		double feather = boundedPercent(featherPercent) / 100.0d;
		double fadeStart = reach * 0.90d * (1 - feather);
		if (depth <= fadeStart)
		{
			return 1;
		}

		double fadeWidth = reach - fadeStart;
		return 1 - smootherstep((depth - fadeStart) / fadeWidth);
	}

	static double contourDepth(
		int width,
		int height,
		double x,
		double y,
		double ignoredCornerSmoothing)
	{
		if (width <= 0 || height <= 0 || !Double.isFinite(x) || !Double.isFinite(y))
		{
			return 0;
		}

		double centerX = (width - 1) * 0.5d;
		double centerY = (height - 1) * 0.5d;
		double axisX = Math.max(0.5d, centerX);
		double axisY = Math.max(0.5d, centerY);
		double radius = roundedRectangleRadius(axisX, axisY);
		double distanceX = Math.abs(x - centerX);
		double distanceY = Math.abs(y - centerY);
		double cornerX = distanceX - (axisX - radius);
		double cornerY = distanceY - (axisY - radius);
		double metric;
		if (cornerX > 0 && cornerY > 0)
		{
			metric = Math.hypot(cornerX, cornerY);
		}
		else if (cornerX > 0)
		{
			metric = cornerX;
		}
		else if (cornerY > 0)
		{
			metric = cornerY;
		}
		else
		{
			metric = Math.max(cornerX, cornerY);
		}
		return radius - metric;
	}

	static double contourCornerOpacity(int width, int height, double x, double y)
	{
		if (width <= 0 || height <= 0 || !Double.isFinite(x) || !Double.isFinite(y))
		{
			return 0.84d;
		}

		return contourCornerOpacityForDepth(
			width,
			height,
			contourDepth(width, height, x, y, 0));
	}

	private static double roundedRectangleRadius(double axisX, double axisY)
	{
		return 0.52d * Math.min(axisX, axisY);
	}

	private static double contourCornerOpacityForDepth(int width, int height, double depth)
	{
		if (width <= 0 || height <= 0 || !Double.isFinite(depth))
		{
			return 0.84d;
		}

		double axisX = Math.max(0.5d, (width - 1) * 0.5d);
		double axisY = Math.max(0.5d, (height - 1) * 0.5d);
		double radius = roundedRectangleRadius(axisX, axisY);
		double maximumOutsideDepth = radius * (Math.sqrt(2) - 1);
		double cornerAmount = maximumOutsideDepth <= 0
			? 0
			: clamp01(-depth / maximumOutsideDepth);
		return 0.84d + 0.16d * smootherstep(cornerAmount);
	}

	static int healthPulseIntervalTicks(double rawSeverity, int escalationPercent)
	{
		double progress = dangerProgress(rawSeverity);
		double exponent = 2.0d - 1.5d * boundedPercent(escalationPercent) / 100.0d;
		double urgency = Math.pow(progress, exponent);
		return 1 + (int) Math.round(3 * (1 - urgency));
	}

	static double healthPulse(
		double gameTicks,
		double rawSeverity,
		int strengthPercent,
		int escalationPercent)
	{
		if (!Double.isFinite(gameTicks) || strengthPercent <= 0)
		{
			return 1;
		}

		double progress = dangerProgress(rawSeverity);
		double amplitude = 0.20d
			* boundedPercent(strengthPercent) / 100.0d
			* (0.30d + 0.70d * smoothstep(progress));
		if (amplitude <= 0)
		{
			return 1;
		}

		int interval = healthPulseIntervalTicks(rawSeverity, escalationPercent);
		long tick = (long) Math.floor(gameTicks);
		double phase = positiveFraction(gameTicks);
		double envelope = 0;
		if (Math.floorMod(tick, interval) == 0 && phase < 0.70d)
		{
			envelope = 0.5d + 0.5d * Math.cos(Math.PI * phase / 0.70d);
		}
		return 1 - amplitude + amplitude * envelope;
	}

	private static double dangerProgress(double rawSeverity)
	{
		double floor = PlayerStatus.VISIBLE_DANGER_FLOOR;
		return clamp01((rawSeverity - floor) / (1.0d - floor));
	}

	private static double animationFactor(
		StatusEffect effect,
		double gameTicks,
		double rawSeverity,
		HealthStatusOverlaysConfig config)
	{
		if (isTransient(effect))
		{
			return 1;
		}
		if (effect == StatusEffect.LOW_HEALTH)
		{
			return healthPulse(
				gameTicks,
				rawSeverity,
				config.healthPulseStrength(),
				config.healthPulseEscalation());
		}
		return 1;
	}

	private static double motionSpeed(StatusEffect effect)
	{
		switch (effect)
		{
			case DISEASE:
				return Math.PI * 2 * 0.12d;
			case POISON:
				return Math.PI * 2 * 0.25d;
			case VENOM:
				return Math.PI * 2 * 0.20d;
			case LOW_PRAYER:
				return Math.PI * 2 * 0.92d;
			case LOW_HEALTH:
				return Math.PI * 2 * 0.78d;
			case FREEZE:
				return Math.PI * 2 * 0.34d;
			default:
				return Math.PI * 2 * 0.24d;
		}
	}

	private static int bandHeight(int width, int height, int depthPercent)
	{
		int shorter = Math.min(width, height);
		int requested = (int) Math.round(shorter * Math.max(0, Math.min(50, depthPercent)) / 100.0d);
		int maximum = Math.max(1, shorter / 2 - 1);
		return Math.max(1, Math.min(maximum, requested));
	}

