		}
	}

	private static double fractalNoise(double x, double y, int seed, double scale)
	{
		double total = 0;
		double weight = 0;
		double amplitude = 1;
		int cell = scaledCell(144, scale);
		for (int octave = 0; octave < 3; octave++)
		{
			total += valueNoise(x, y, cell, seed + octave * 37) * amplitude;
			weight += amplitude;
			amplitude *= 0.52d;
			cell = Math.max(scaledCell(24, scale), cell / 2);
		}
		return total / weight;
	}

	private static double valueNoise(double x, double y, int cellSize, int seed)
	{
		int cellX = (int) Math.floor(x / cellSize);
		int cellY = (int) Math.floor(y / cellSize);
		double fractionX = (x - cellX * (double) cellSize) / cellSize;
		double fractionY = (y - cellY * (double) cellSize) / cellSize;
		double smoothX = smootherstep(fractionX);
		double smoothY = smootherstep(fractionY);
		double topLeft = hashUnit(cellX, cellY, seed);
		double topRight = hashUnit(cellX + 1, cellY, seed);
		double bottomLeft = hashUnit(cellX, cellY + 1, seed);
		double bottomRight = hashUnit(cellX + 1, cellY + 1, seed);
		double top = interpolate(topLeft, topRight, smoothX);
		double bottom = interpolate(bottomLeft, bottomRight, smoothX);
		return interpolate(top, bottom, smoothY);
	}

	private static double worley(double x, double y, int cellSize, int seed)
	{
		int baseX = (int) Math.floor(x / cellSize);
		int baseY = (int) Math.floor(y / cellSize);
		double nearestSquared = Double.MAX_VALUE;
		for (int offsetY = -1; offsetY <= 1; offsetY++)
		{
			for (int offsetX = -1; offsetX <= 1; offsetX++)
			{
				int cellX = baseX + offsetX;
				int cellY = baseY + offsetY;
				double featureX = (cellX + hashUnit(cellX, cellY, seed + 3)) * cellSize;
				double featureY = (cellY + hashUnit(cellX, cellY, seed + 7)) * cellSize;
				double dx = x - featureX;
				double dy = y - featureY;
				nearestSquared = Math.min(nearestSquared, dx * dx + dy * dy);
			}
		}
		return clamp01(Math.sqrt(nearestSquared) / (cellSize * Math.sqrt(2)));
	}

	private static double hashUnit(int x, int y, int seed)
	{
		int hash = x * 0x1f1f1f1f ^ y * 0x5f356495 ^ seed * 0x6c8e9cf5;
		hash ^= hash >>> 16;
		hash *= 0x7feb352d;
		hash ^= hash >>> 15;
		hash *= 0x846ca68b;
		hash ^= hash >>> 16;
		return (hash & 0x00ffffff) / 16777216.0d;
	}

	private static int coloredPixel(Color color, int alpha, double brightness)
	{
		int red = clamp255((int) Math.round(color.getRed() * brightness));
		int green = clamp255((int) Math.round(color.getGreen() * brightness));
		int blue = clamp255((int) Math.round(color.getBlue() * brightness));
		return premultipliedArgb(alpha, red, green, blue);
	}

	private static int premultipliedArgb(int alpha, int red, int green, int blue)
	{
		int premultipliedRed = red * alpha / 255;
		int premultipliedGreen = green * alpha / 255;
		int premultipliedBlue = blue * alpha / 255;
		return alpha << 24 | premultipliedRed << 16 | premultipliedGreen << 8 | premultipliedBlue;
	}

	private static Color darken(Color color, double factor)
	{
		return new Color(
			clamp255((int) Math.round(color.getRed() * factor)),
			clamp255((int) Math.round(color.getGreen() * factor)),
			clamp255((int) Math.round(color.getBlue() * factor)));
	}

	private static Color mixWithWhite(Color color, double amount)
	{
		double bounded = clamp01(amount);
		return new Color(
			clamp255((int) Math.round(interpolate(color.getRed(), 255, bounded))),
			clamp255((int) Math.round(interpolate(color.getGreen(), 255, bounded))),
			clamp255((int) Math.round(interpolate(color.getBlue(), 255, bounded))));
	}

	private static double ridge(double value)
	{
		return 1 - Math.abs(2 * clamp01(value) - 1);
	}

	private static double square(double value)
	{
		return value * value;
	}

	private static double smoothstep(double value)
	{
		double bounded = clamp01(value);
		return bounded * bounded * (3 - 2 * bounded);
	}

	private static double smootherstep(double value)
	{
		double bounded = clamp01(value);
		return bounded * bounded * bounded * (bounded * (bounded * 6 - 15) + 10);
	}

	private static double smoothstepRange(double start, double end, double value)
	{
		if (end <= start)
		{
			return value >= end ? 1 : 0;
		}
		return smoothstep((value - start) / (end - start));
	}

	private static double interpolate(double start, double end, double amount)
	{
		return start + (end - start) * amount;
	}

	private static double positiveFraction(double value)
	{
		return value - Math.floor(value);
	}

	private static int boundedPercent(int value)
	{
		return Math.max(0, Math.min(100, value));
	}

	private static double clamp01(double value)
	{
		return Math.max(0, Math.min(1, value));
	}

	private static int clamp255(int value)
	{
		return Math.max(0, Math.min(255, value));
	}

