	private static final class ContourKey
	{
		private final StatusEffect effect;
		private final int width;
		private final int height;
		private final int band;
		private final int feather;
		private final int color;

		private ContourKey(
			StatusEffect effect,
			int width,
			int height,
			int band,
			int feather,
			int color)
		{
			this.effect = effect;
			this.width = width;
			this.height = height;
			this.band = band;
			this.feather = feather;
			this.color = color;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof ContourKey))
			{
				return false;
			}

			ContourKey key = (ContourKey) other;
			return width == key.width
				&& height == key.height
				&& band == key.band
				&& feather == key.feather
				&& color == key.color
				&& effect == key.effect;
		}

		@Override
		public int hashCode()
		{
			int result = effect.hashCode();
			result = 31 * result + width;
			result = 31 * result + height;
			result = 31 * result + band;
			result = 31 * result + feather;
			result = 31 * result + color;
			return result;
		}
	}
