package com.healthstatusoverlays;

final class StatusEffects
{
	static final StatusEffects NONE = new StatusEffects(0, 0, 0, 0, 0, 0, 0, 0, 0);

	private final double disease;
	private final double poison;
	private final double venom;
	private final double lowPrayer;
	private final double lowHealth;
	private final double freeze;
	private final double damage;
	private final double poisonTick;
	private final double venomTick;

	StatusEffects(
		double disease,
		double poison,
		double venom,
		double lowPrayer,
		double lowHealth,
		double freeze)
	{
		this(disease, poison, venom, lowPrayer, lowHealth, freeze, 0, 0, 0);
	}

	StatusEffects(
		double disease,
		double poison,
		double venom,
		double lowPrayer,
		double lowHealth,
		double freeze,
		double damage,
		double poisonTick,
		double venomTick)
	{
		this.disease = clamp01(disease);
		this.poison = clamp01(poison);
		this.venom = clamp01(venom);
		this.lowPrayer = clamp01(lowPrayer);
		this.lowHealth = clamp01(lowHealth);
		this.freeze = clamp01(freeze);
		this.damage = clamp01(damage);
		this.poisonTick = clamp01(poisonTick);
		this.venomTick = clamp01(venomTick);
	}

	double get(StatusEffect effect)
	{
		switch (effect)
		{
			case DISEASE:
				return disease;
			case POISON:
				return poison;
			case VENOM:
				return venom;
			case LOW_PRAYER:
				return lowPrayer;
			case LOW_HEALTH:
				return lowHealth;
			case FREEZE:
				return freeze;
			case DAMAGE:
				return damage;
			case POISON_TICK:
				return poisonTick;
			case VENOM_TICK:
				return venomTick;
			default:
				return 0;
		}
	}

	boolean isEmpty()
	{
		return disease == 0
			&& poison == 0
			&& venom == 0
			&& lowPrayer == 0
			&& lowHealth == 0
			&& freeze == 0
			&& damage == 0
			&& poisonTick == 0
			&& venomTick == 0;
	}

	StatusEffects mergeMax(StatusEffects other)
	{
		if (other == null || other.isEmpty())
		{
			return this;
		}
		if (isEmpty())
		{
			return other;
		}

		return new StatusEffects(
			Math.max(disease, other.disease),
			Math.max(poison, other.poison),
			Math.max(venom, other.venom),
			Math.max(lowPrayer, other.lowPrayer),
			Math.max(lowHealth, other.lowHealth),
			Math.max(freeze, other.freeze),
			Math.max(damage, other.damage),
			Math.max(poisonTick, other.poisonTick),
			Math.max(venomTick, other.venomTick));
	}

	static StatusEffects preview(EffectPreview preview)
	{
		if (preview == null)
		{
			return NONE;
		}

		switch (preview)
		{
			case ALL:
				return new StatusEffects(1, 1, 1, 1, 1, 1);
			case DISEASE:
				return new StatusEffects(1, 0, 0, 0, 0, 0);
			case POISON:
				return new StatusEffects(0, 1, 0, 0, 0, 0);
			case VENOM:
				return new StatusEffects(0, 0, 1, 0, 0, 0);
			case LOW_PRAYER:
				return new StatusEffects(0, 0, 0, 1, 0, 0);
			case LOW_HEALTH:
				return new StatusEffects(0, 0, 0, 0, 1, 0);
			case FREEZE:
				return new StatusEffects(0, 0, 0, 0, 0, 1);
			case DAMAGE_FEEDBACK:
				return new StatusEffects(0, 0, 0, 0, 0, 0, 1, 0, 0);
			default:
				return NONE;
		}
	}

	private static double clamp01(double value)
	{
		return Math.max(0, Math.min(1, value));
	}
}

package com.healthstatusoverlays;

/**
 * Tracks local hitpoint loss as a short visual impulse without depending on Client.
 */
final class ImpactTracker
{
	private static final long NANOS_PER_MILLISECOND = 1_000_000L;
	private static final int DEFAULT_MINIMUM_RESPONSE_PERCENT = 5;

	private int previousHealth = -1;
	private long startedNanos = -1;
	private double peak;

	void reset()
	{
		previousHealth = -1;
		startedNanos = -1;
		peak = 0;
	}

	void seedHealth(int health)
	{
		if (previousHealth < 0)
		{
			previousHealth = Math.max(0, health);
		}
	}

	boolean observeHealth(int health, int maximumHealth, long nowNanos, int durationMillis)
	{
		return observeHealth(
			health,
			maximumHealth,
			nowNanos,
			durationMillis,
			DEFAULT_MINIMUM_RESPONSE_PERCENT);
	}

	boolean observeHealth(
		int health,
		int maximumHealth,
		long nowNanos,
		int durationMillis,
		int minimumResponsePercent)
	{
		int boundedHealth = Math.max(0, health);
		if (previousHealth < 0)
		{
			previousHealth = boundedHealth;
			return false;
		}

		int lost = Math.max(0, previousHealth - boundedHealth);
		previousHealth = boundedHealth;
		if (lost <= 0 || maximumHealth <= 0 || nowNanos < 0)
		{
			return false;
		}
		return triggerDamage(
			lost,
			maximumHealth,
			nowNanos,
			durationMillis,
			minimumResponsePercent);
	}

	boolean triggerDamage(int damage, int maximumHealth, long nowNanos, int durationMillis)
	{
		return triggerDamage(
			damage,
			maximumHealth,
			nowNanos,
			durationMillis,
			DEFAULT_MINIMUM_RESPONSE_PERCENT);
	}

	boolean triggerDamage(
		int damage,
		int maximumHealth,
		long nowNanos,
		int durationMillis,
		int minimumResponsePercent)
	{
		if (damage <= 0 || maximumHealth <= 0 || nowNanos < 0 || durationMillis <= 0)
		{
			return false;
		}
		return triggerSeverity(
			impactSeverity(damage, maximumHealth, minimumResponsePercent),
			nowNanos,
			durationMillis);
	}

	boolean triggerSeverity(double severity, long nowNanos, int durationMillis)
	{
		if (!Double.isFinite(severity) || severity <= 0 || nowNanos < 0 || durationMillis <= 0)
		{
			return false;
		}

		double incoming = clamp01(severity);
		double remaining = strength(nowNanos, durationMillis, 100);
		peak = 1 - (1 - remaining) * (1 - incoming);
		startedNanos = nowNanos;
		return true;
	}

	double strength(long nowNanos, int durationMillis, int strengthPercent)
	{
		if (startedNanos < 0 || nowNanos < startedNanos || durationMillis <= 0 || strengthPercent <= 0)
		{
			return 0;
		}

		long durationNanos = durationMillis * NANOS_PER_MILLISECOND;
		long elapsedNanos = nowNanos - startedNanos;
		if (elapsedNanos >= durationNanos)
		{
			return 0;
		}

		double progress = elapsedNanos / (double) durationNanos;
		return clamp01(peak * decay(progress) * boundedPercent(strengthPercent) / 100.0d);
	}

	static double previewStrength(
		long nowNanos,
		int durationMillis,
		int intervalSeconds,
		int hitPercent,
		int strengthPercent)
	{
		return previewStrength(
			nowNanos,
			durationMillis,
			intervalSeconds,
			hitPercent,
			strengthPercent,
			DEFAULT_MINIMUM_RESPONSE_PERCENT);
	}

	static double previewStrength(
		long nowNanos,
		int durationMillis,
		int intervalSeconds,
		int hitPercent,
		int strengthPercent,
		int minimumResponsePercent)
	{
		if (nowNanos < 0 || durationMillis <= 0 || intervalSeconds <= 0 || hitPercent <= 0 || strengthPercent <= 0)
		{
			return 0;
		}

		long durationNanos = durationMillis * NANOS_PER_MILLISECOND;
		long intervalNanos = Math.max(
			durationNanos + 250L * NANOS_PER_MILLISECOND,
			intervalSeconds * 1_000L * NANOS_PER_MILLISECOND);
		long elapsed = nowNanos % intervalNanos;
		if (elapsed >= durationNanos)
		{
			return 0;
		}

		return previewSeverityStrength(
			nowNanos,
			durationMillis,
			intervalSeconds,
			impactSeverity(hitPercent, 100, minimumResponsePercent),
			strengthPercent);
	}

	static double previewSeverityStrength(
		long nowNanos,
		int durationMillis,
		int intervalSeconds,
		double peakSeverity,
		int strengthPercent)
	{
		if (nowNanos < 0 || durationMillis <= 0 || intervalSeconds <= 0
			|| !Double.isFinite(peakSeverity) || peakSeverity <= 0 || strengthPercent <= 0)
		{
			return 0;
		}

		long durationNanos = durationMillis * NANOS_PER_MILLISECOND;
		long intervalNanos = Math.max(
			durationNanos + 250L * NANOS_PER_MILLISECOND,
			intervalSeconds * 1_000L * NANOS_PER_MILLISECOND);
		long elapsed = nowNanos % intervalNanos;
		if (elapsed >= durationNanos)
		{
			return 0;
		}

		double progress = elapsed / (double) durationNanos;
		return clamp01(clamp01(peakSeverity) * decay(progress) * boundedPercent(strengthPercent) / 100.0d);
	}

	static double impactSeverity(int damage, int maximumHealth)
	{
		return impactSeverity(damage, maximumHealth, DEFAULT_MINIMUM_RESPONSE_PERCENT);
	}

	static double impactSeverity(int damage, int maximumHealth, int minimumResponsePercent)
	{
		if (damage <= 0 || maximumHealth <= 0)
		{
			return 0;
		}

		double scaledDamage = clamp01(damage / (double) maximumHealth);
		double heavyHitResponse = 1 - Math.pow(1 - scaledDamage, 3);
		double minimumResponse = boundedPercent(minimumResponsePercent) / 100.0d;
		return minimumResponse
			+ (1 - minimumResponse) * heavyHitResponse;
	}

	static double decay(double progress)
	{
		double bounded = clamp01(progress);
		double smooth = bounded * bounded * (3 - 2 * bounded);
		return 1 - smooth;
	}

	private static int boundedPercent(int value)
	{
		return Math.max(0, Math.min(100, value));
	}

	private static double clamp01(double value)
	{
		return Math.max(0, Math.min(1, value));
	}
}

package com.healthstatusoverlays;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class HealthStatusOverlay extends Overlay
{
	private final Client client;
	private final HealthStatusOverlaysPlugin plugin;
	private final HealthStatusOverlaysConfig config;
	private final ProceduralRenderer renderer = new ProceduralRenderer();

	@Inject
	HealthStatusOverlay(Client client, HealthStatusOverlaysPlugin plugin, HealthStatusOverlaysConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return null;
		}

		long nowNanos = System.nanoTime();
		renderer.render(
			graphics,
			client.getCanvasWidth(),
			client.getCanvasHeight(),
			plugin.getEffects(),
			config,
			nowNanos / 1_000_000_000.0,
			plugin.getGameTickClock(nowNanos));
		return null;
	}

	void clearCache()
	{
		renderer.clearCache();
	}
}

