import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Health & Status Overlays",
	description = "Screen overlays for low health, damage, prayer, poison, venom, disease and freeze",
	tags = {"health", "hp", "hitpoints", "damage", "blood", "prayer", "poison", "venom", "disease", "freeze", "ice", "status", "effects", "overlay", "vignette", "warning", "notifications"}
)
public class HealthStatusOverlaysPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(HealthStatusOverlaysPlugin.class);
	private static final long GAME_TICK_NANOS = 600_000_000L;
	private static final String FROZEN_MESSAGE = "You have been frozen!";
	private static final int[] IMMOBILIZATION_GRAPHICS =
	{
		SpotanimID.BIND_IMPACT,
		SpotanimID.SNARE_IMPACT,
		SpotanimID.ENTANGLE_IMPACT,
		SpotanimID.ICE_RUSH_IMPACT,
		SpotanimID.ICE_BLITZ_IMPACT,
		SpotanimID.ICE_BURST_IMPACT,
		SpotanimID.ICE_BARRAGE_IMPACT
	};
	private static final PlayerStatus EMPTY_STATUS =
		new PlayerStatus(0, 0, 0, 0, 0, 0, 0);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HealthStatusOverlay overlay;

	@Inject
	private HealthStatusOverlaysConfig config;

	private final FreezeTracker freezeTracker = new FreezeTracker();
	private final ImpactTracker impactTracker = new ImpactTracker();
	private final ImpactTracker poisonTickTracker = new ImpactTracker();
	private final ImpactTracker venomTickTracker = new ImpactTracker();
	private final Set<Integer> activeImmobilizationGraphics = new HashSet<>();
	private volatile PlayerStatus status = EMPTY_STATUS;
	private volatile boolean prayerActive;
	private volatile long previewFeedbackStartedNanos;
	private volatile int animationGameTick;
	private volatile long animationGameTickStartedNanos = -1;

	@Provides
	HealthStatusOverlaysConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HealthStatusOverlaysConfig.class);
	}

	@Override
	protected void startUp()
	{
		freezeTracker.reset();
		impactTracker.reset();
		poisonTickTracker.reset();
		venomTickTracker.reset();
		activeImmobilizationGraphics.clear();
		long nowNanos = System.nanoTime();
		previewFeedbackStartedNanos = nowNanos;
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			recordGameTick(System.nanoTime());
			refreshStatus();
		});
		log.debug("Health & Status Overlays started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.clearCache();
		clearState();
		log.debug("Health & Status Overlays stopped");
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		recordGameTick(System.nanoTime());
		Player player = client.getLocalPlayer();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN && player != null;
		freezeTracker.advance(
			client.getTickCount(),
			positionKey(player),
			loggedIn && !player.isDead(),
			loggedIn);
		refreshStatus();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			clearState();
			return;
		}

		recordGameTick(System.nanoTime());
		refreshStatus();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.POISON || event.getVarpId() == VarPlayerID.DISEASE)
		{
			refreshStatus();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.HITPOINTS)
		{
			if (client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null)
			{
				impactTracker.observeHealth(
					event.getBoostedLevel(),
					client.getRealSkillLevel(Skill.HITPOINTS),
					System.nanoTime(),
					config.damageFeedbackDuration(),
					config.damageMinimumResponse());
			}
			refreshStatus();
		}
		else if (event.getSkill() == Skill.PRAYER)
		{
			refreshStatus();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getActor() != client.getLocalPlayer() || event.getActor() == null)
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		if (hitsplat == null)
		{
			return;
		}

		ImpactTracker tracker;
		double severity;
		if (hitsplat.getHitsplatType() == HitsplatID.POISON)
		{
			tracker = poisonTickTracker;
			severity = toxinTickSeverity(hitsplat.getAmount(), false);
		}
		else if (hitsplat.getHitsplatType() == HitsplatID.VENOM)
		{
			tracker = venomTickTracker;
			severity = toxinTickSeverity(hitsplat.getAmount(), true);
		}
		else
		{
			return;
		}

		tracker.triggerSeverity(
			severity,
			System.nanoTime(),
			config.damageFeedbackDuration());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		if (!FROZEN_MESSAGE.equals(Text.removeTags(event.getMessage()).trim()))
		{
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		freezeTracker.confirmIce(client.getTickCount(), positionKey(player));
		refreshStatus();
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		Player player = client.getLocalPlayer();
		if (event.getActor() != player || player == null)
		{
			return;
		}

		int tick = client.getTickCount();
		long position = positionKey(player);
		for (int graphicId : IMMOBILIZATION_GRAPHICS)
		{
			boolean active = player.hasSpotAnim(graphicId);
			if (active && activeImmobilizationGraphics.add(graphicId))
			{
				freezeTracker.observeGraphic(graphicId, tick, position);
			}
			else if (!active)
			{
				activeImmobilizationGraphics.remove(graphicId);
			}
		}
		refreshStatus();
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			freezeTracker.reset();
			impactTracker.reset();
			poisonTickTracker.reset();
			venomTickTracker.reset();
			activeImmobilizationGraphics.clear();
			refreshStatus();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!HealthStatusOverlaysConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (resetsPreviewFeedback(event.getKey()))
		{
			previewFeedbackStartedNanos = System.nanoTime();
		}
	}

	StatusEffects getEffects()
	{
		long nowNanos = System.nanoTime();
		PlayerStatus snapshot = status;
		double disease = config.diseaseEnabled() && snapshot.isDiseased()
			? snapshot.diseaseStrength()
			: 0;
		double poison = config.poisonEnabled() && snapshot.isPoisoned()
			? poisonSeverity(snapshot.poisonDamage())
			: 0;
		double venom = config.venomEnabled() && snapshot.isVenomed()
			? venomSeverity(snapshot.venomDamage())
			: 0;
		double lowPrayer = config.lowPrayerEnabled()
			&& (!config.prayerActiveOnly() || prayerActive)
			? snapshot.lowPrayerStrength(config.lowPrayerThreshold())
			: 0;
		double lowHealth = config.lowHealthEnabled()
			? snapshot.lowHealthStrength(config.lowHealthThreshold())
			: 0;
		double freeze = config.freezeEnabled() && snapshot.freezeStrength() > 0
			? 0.40 + 0.60 * smoothstep(snapshot.freezeStrength())
			: 0;
		double damage = config.damageFeedbackEnabled()
			? impactTracker.strength(
				nowNanos,
				config.damageFeedbackDuration(),
				config.damageFeedbackStrength())
			: 0;
		double poisonTick = config.damageFeedbackEnabled() && config.poisonEnabled()
			? poisonTickTracker.strength(
				nowNanos,
				config.damageFeedbackDuration(),
				config.damageFeedbackStrength())
			: 0;
		double venomTick = config.damageFeedbackEnabled() && config.venomEnabled()
			? venomTickTracker.strength(
				nowNanos,
				config.damageFeedbackDuration(),
				config.damageFeedbackStrength())
			: 0;

		StatusEffects liveEffects = new StatusEffects(
			disease,
			poison,
			venom,
			lowPrayer,
			lowHealth,
			freeze,
			damage,
			poisonTick,
			venomTick);

		EffectPreview preview = config.preview();
		if (preview == null || preview == EffectPreview.OFF)
		{
			return liveEffects;
		}

		long previewElapsed = Math.max(0, nowNanos - previewFeedbackStartedNanos);
		return liveEffects.mergeMax(previewEffects(config, previewElapsed));
	}

	static StatusEffects previewEffects(HealthStatusOverlaysConfig config, long elapsedNanos)
	{
		EffectPreview preview = config.preview();
		if (preview == null || preview == EffectPreview.OFF)
		{
			return StatusEffects.NONE;
		}

		double disease = 0;
		double poison = 0;
		double venom = 0;
		double lowPrayer = 0;
		double lowHealth = 0;
		double freeze = 0;
		double damage = 0;
		double poisonTick = 0;
		double venomTick = 0;

		if (preview == EffectPreview.ALL || preview == EffectPreview.DISEASE)
		{
			disease = boundedPercent(config.previewDiseaseSeverity());
		}
		if (preview == EffectPreview.ALL || preview == EffectPreview.POISON)
		{
			poison = poisonSeverity(config.previewPoisonDamage());
		}
		if (preview == EffectPreview.ALL || preview == EffectPreview.VENOM)
		{
			venom = venomSeverity(config.previewVenomDamage());
		}
		if (preview == EffectPreview.ALL || preview == EffectPreview.LOW_PRAYER)
		{
			lowPrayer = PlayerStatus.thresholdDangerStrength(
				config.previewPrayerPercent(),
				100,
				config.lowPrayerThreshold());
		}
		if (preview == EffectPreview.ALL || preview == EffectPreview.LOW_HEALTH)
		{
			lowHealth = PlayerStatus.thresholdDangerStrength(
				config.previewHealthPercent(),
				100,
				config.lowHealthThreshold());
		}
		if (preview == EffectPreview.ALL || preview == EffectPreview.FREEZE)
		{
			double remaining = boundedPercent(config.previewFreezeRemaining());
			freeze = remaining > 0 ? 0.40d + 0.60d * smoothstep(remaining) : 0;
		}

		boolean replay = preview == EffectPreview.DAMAGE_FEEDBACK
			|| config.replayPreviewFeedback();
		if (replay)
		{
			if (preview == EffectPreview.ALL || preview == EffectPreview.LOW_HEALTH
				|| preview == EffectPreview.DAMAGE_FEEDBACK)
			{
				damage = previewFeedbackStrength(config, elapsedNanos, config.previewDamageSize());
			}
			if (preview == EffectPreview.ALL || preview == EffectPreview.POISON)
			{
				poisonTick = previewToxinFeedbackStrength(
					config,
					elapsedNanos,
					config.previewPoisonDamage(),
					false);
			}
			if (preview == EffectPreview.ALL || preview == EffectPreview.VENOM)
			{
				venomTick = previewToxinFeedbackStrength(
					config,
					elapsedNanos,
					config.previewVenomDamage(),
					true);
			}
		}

		return new StatusEffects(
			disease,
			poison,
			venom,
			lowPrayer,
			lowHealth,
			freeze,
			damage,
			poisonTick,
			venomTick);
	}

	PlayerStatus getStatus()
	{
		return status;
	}

	double getGameTickClock(long nowNanos)
	{
		return gameTickClock(
			animationGameTick,
			animationGameTickStartedNanos,
			nowNanos);
	}

	static double gameTickClock(int gameTick, long tickStartedNanos, long nowNanos)
	{
		if (tickStartedNanos < 0 || nowNanos <= tickStartedNanos)
		{
			return gameTick;
		}

		double phase = Math.min(0.999_999d, (nowNanos - tickStartedNanos) / (double) GAME_TICK_NANOS);
		return gameTick + phase;
	}

	private void refreshStatus()
	{
		Player player = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || player == null)
		{
			status = EMPTY_STATUS;
			prayerActive = false;
			return;
		}

		int health = client.getBoostedSkillLevel(Skill.HITPOINTS);
		impactTracker.seedHealth(health);
		status = new PlayerStatus(
			client.getVarpValue(VarPlayerID.POISON),
			health,
			client.getRealSkillLevel(Skill.HITPOINTS),
			client.getBoostedSkillLevel(Skill.PRAYER),
			client.getRealSkillLevel(Skill.PRAYER),
			client.getVarpValue(VarPlayerID.DISEASE),
			freezeTracker.strength(client.getTickCount()));
		prayerActive = hasActivePrayer();
	}

	private boolean hasActivePrayer()
	{
		for (Prayer prayer : Prayer.values())
		{
			if (client.getVarbitValue(prayer.getVarbit()) != 0)
			{
				return true;
			}
		}
		return false;
	}

	private void clearState()
	{
		freezeTracker.reset();
		impactTracker.reset();
		poisonTickTracker.reset();
		venomTickTracker.reset();
		activeImmobilizationGraphics.clear();
		status = EMPTY_STATUS;
		prayerActive = false;
		previewFeedbackStartedNanos = System.nanoTime();
		animationGameTick = 0;
		animationGameTickStartedNanos = -1;
	}

	private void recordGameTick(long nowNanos)
	{
		animationGameTick = client.getTickCount();
		animationGameTickStartedNanos = nowNanos;
	}

	private static long positionKey(Player player)
	{
		if (player == null)
		{
			return 0;
		}

		WorldPoint point = player.getWorldLocation();
		return ((long) point.getPlane() & 0x3L) << 42
			| ((long) point.getX() & 0x1fffffL) << 21
			| (long) point.getY() & 0x1fffffL;
	}

	private static boolean resetsPreviewFeedback(String key)
	{
		return "preview".equals(key)
			|| "replayPreviewFeedback".equals(key)
			|| "previewDamageSize".equals(key)
			|| "previewPoisonDamage".equals(key)
			|| "previewVenomDamage".equals(key)
			|| "previewFeedbackInterval".equals(key)
			|| "damageFeedbackDuration".equals(key)
			|| "damageFeedbackStrength".equals(key)
			|| "damageMinimumResponse".equals(key);
	}

	private static double smoothstep(double value)
	{
		double bounded = Math.max(0, Math.min(1, value));
		return bounded * bounded * (3 - 2 * bounded);
	}

	static double poisonSeverity(int damage)
	{
		if (damage <= 0)
		{
			return 0;
		}
		double progress = Math.max(0, Math.min(1, (damage - 1) / 19.0d));
		return 0.60d + 0.40d * progress;
	}

	static double venomSeverity(int damage)
	{
		return toxinSeverity(damage, 0.55d, 0.45d);
	}

	static double toxinTickSeverity(int damage, boolean venom)
	{
		if (damage <= 0)
		{
			return 0;
		}
		double persistent = venom ? venomSeverity(damage) : poisonSeverity(damage);
		return 0.35d + 0.65d * persistent;
	}

	private static double toxinSeverity(int damage, double floor, double range)
	{
		if (damage <= 0)
		{
			return 0;
		}
		double normalized = Math.max(0, Math.min(1, damage / 20.0d));
		return floor + range * Math.sqrt(normalized);
	}

	private static double boundedPercent(int value)
	{
		return Math.max(0, Math.min(100, value)) / 100.0d;
	}

	private static double previewFeedbackStrength(
		HealthStatusOverlaysConfig config,
		long elapsedNanos,
		int hitPercent)
	{
		return ImpactTracker.previewStrength(
			elapsedNanos,
			config.damageFeedbackDuration(),
			config.previewFeedbackInterval(),
			hitPercent,
			config.damageFeedbackStrength(),
			config.damageMinimumResponse());
	}

	private static double previewToxinFeedbackStrength(
		HealthStatusOverlaysConfig config,
		long elapsedNanos,
		int damage,
		boolean venom)
	{
		return ImpactTracker.previewSeverityStrength(
			elapsedNanos,
			config.damageFeedbackDuration(),
			config.previewFeedbackInterval(),
			toxinTickSeverity(damage, venom),
			config.damageFeedbackStrength());
	}
}

package com.healthstatusoverlays;

/**
 * Immutable snapshot of the raw values used by the status overlay.
 */
public final class PlayerStatus
{
	public static final int VENOM_THRESHOLD = 1_000_000;
	public static final double VISIBLE_DANGER_FLOOR = 0.35d;

	private static final int MAXIMUM_STANDARD_STATUS_DAMAGE = 20;
	private static final int POISON_IMMUNITY_OFFSET = 38;
	private static final int IMMUNITY_TICK_MULTIPLIER = 30;

	private final int poisonValue;
	private final int health;
	private final int maximumHealth;
	private final int prayer;
	private final int maximumPrayer;
	private final int diseaseValue;
	private final double freezeStrength;

	public PlayerStatus(
		int poisonValue,
		int health,
		int maximumHealth,
		int prayer,
		int maximumPrayer,
		int diseaseValue,
		double freezeStrength)
	{
		this.poisonValue = poisonValue;
		this.health = health;
		this.maximumHealth = maximumHealth;
		this.prayer = prayer;
		this.maximumPrayer = maximumPrayer;
		this.diseaseValue = diseaseValue;
		this.freezeStrength = clampStrength(freezeStrength);
	}

	public int poisonValue()
	{
		return poisonValue;
	}

	public int health()
	{
		return health;
	}

	public int maximumHealth()
	{
		return maximumHealth;
	}

	public int prayer()
	{
		return prayer;
	}

	public int maximumPrayer()
	{
		return maximumPrayer;
	}

	public int diseaseValue()
	{
		return diseaseValue;
	}

	public boolean hasPoisonImmunity()
	{
		return poisonValue < 0;
	}

	public boolean hasVenomImmunity()
	{
		return poisonValue < -POISON_IMMUNITY_OFFSET;
	}

	public int immunityTicks()
	{
		if (!hasPoisonImmunity())
		{
			return 0;
		}

		long magnitude = -(long) poisonValue;
		if (hasVenomImmunity())
		{
			magnitude -= POISON_IMMUNITY_OFFSET;
		}

		return saturatingInt(magnitude * IMMUNITY_TICK_MULTIPLIER);
	}

	public boolean isPoisoned()
	{
		return poisonValue > 0 && poisonValue < VENOM_THRESHOLD;
	}

	public boolean isVenomed()
	{
		return poisonValue >= VENOM_THRESHOLD;
	}

	public int poisonDamage()
	{
		if (!isPoisoned())
		{
			return 0;
		}

		return (poisonValue + 4) / 5;
	}

	public int venomDamage()
	{
		if (!isVenomed())
		{
			return 0;
		}

		long damage = ((long) poisonValue - 999_997L) * 2L;
		return (int) Math.min(MAXIMUM_STANDARD_STATUS_DAMAGE, damage);
	}

	public boolean isDiseased()
	{
		return diseaseValue > 0;
	}

	public double poisonStrength()
	{
		return damageStrength(poisonDamage());
	}

	public double venomStrength()
	{
		return damageStrength(venomDamage());
	}

	public double lowHealthStrength(int thresholdPercent)
	{
		return thresholdDangerStrength(health, maximumHealth, thresholdPercent);
	}

	public double lowPrayerStrength(int thresholdPercent)
	{
		return thresholdDangerStrength(prayer, maximumPrayer, thresholdPercent);
	}

	public double diseaseStrength()
	{
		return binaryStrength(isDiseased());
	}

	public double freezeStrength()
	{
		return freezeStrength;
	}

	public static double thresholdDangerStrength(int current, int maximum, int thresholdPercent)
	{
		if (maximum <= 0 || thresholdPercent <= 0)
		{
			return 0.0d;
		}

		int boundedThreshold = Math.min(100, thresholdPercent);
		double threshold = maximum * boundedThreshold / 100.0d;
		if (current > threshold)
		{
			return 0.0d;
		}

		double boundedCurrent = Math.max(0.0d, current);
		double progress = 1.0d - boundedCurrent / threshold;
		double strength = VISIBLE_DANGER_FLOOR
			+ progress * (1.0d - VISIBLE_DANGER_FLOOR);
		return clampStrength(strength);
	}

	public static double binaryStrength(boolean active)
	{
		return active ? 1.0d : 0.0d;
	}

	public static double clampStrength(double strength)
	{
		if (!Double.isFinite(strength) || strength <= 0.0d)
		{
			return 0.0d;
		}

		return Math.min(1.0d, strength);
	}

	private static double damageStrength(int damage)
	{
		return clampStrength(damage / (double) MAXIMUM_STANDARD_STATUS_DAMAGE);
	}

	private static int saturatingInt(long value)
	{
		return value >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) value;
	}
}

package com.healthstatusoverlays;

import net.runelite.api.gameval.SpotanimID;

/**
 * Tracks confirmed local-player immobilization without depending on Client or WorldPoint.
 */
public final class FreezeTracker
{
	public static final int ICE_FALLBACK_TICKS = 32;

	public enum FreezeType
	{
		BIND(8, false),
		SNARE(16, false),
		ENTANGLE(24, false),
		ICE_RUSH(8, true),
		ICE_BURST(16, true),
		ICE_BLITZ(24, true),
		ICE_BARRAGE(ICE_FALLBACK_TICKS, true);

		private final int durationTicks;
		private final boolean ice;

		FreezeType(int durationTicks, boolean ice)
		{
			this.durationTicks = durationTicks;
			this.ice = ice;
		}

		public int durationTicks()
		{
			return durationTicks;
		}

		public boolean isIce()
		{
			return ice;
		}
	}

	private FreezeType type;
	private int applicationTick;
	private int expiryTick;
	private int observedTick;
	private long positionKey;

	public void confirmIce(int tick, long positionKey)
	{
		apply(FreezeType.ICE_BARRAGE, tick, positionKey);
	}

	/**
	 * Observes a local-player impact graphic.
	 *
	 * @return true when the graphic started or refined tracked immobilization
	 */
	public boolean observeGraphic(int graphicId, int tick, long positionKey)
	{
		FreezeType observedType = typeForGraphic(graphicId);
		if (observedType == null)
		{
			return false;
		}

		if (!observedType.isIce())
		{
			apply(observedType, tick, positionKey);
			return true;
		}

		if (type == null
			|| !type.isIce()
			|| tick != applicationTick
			|| positionKey != this.positionKey)
		{
			return false;
		}

		apply(observedType, applicationTick, positionKey);
		return true;
	}

	public void advance(int tick, long positionKey)
	{
		advance(tick, positionKey, true, true);
	}

	public void advance(int tick, long positionKey, boolean alive, boolean loggedIn)
	{
		observedTick = tick;
		if (!alive || !loggedIn || type == null || tick < applicationTick || tick >= expiryTick)
		{
			reset();
			return;
		}

		if (tick == applicationTick)
		{
			this.positionKey = positionKey;
			return;
		}

		if (positionKey != this.positionKey)
		{
			reset();
		}
	}

	public void reset()
	{
		type = null;
		applicationTick = 0;
		expiryTick = 0;
		observedTick = 0;
		positionKey = 0L;
	}

	public boolean isActive()
	{
		return type != null;
	}

	public boolean isActive(int tick)
	{
		return type != null && tick >= applicationTick && tick < expiryTick;
	}

	public FreezeType type()
	{
		return type;
	}

	public int applicationTick()
	{
		return applicationTick;
	}

	public int expiryTick()
	{
		return expiryTick;
	}

	public long positionKey()
	{
		return positionKey;
	}

	public int durationTicks()
	{
		return type == null ? 0 : type.durationTicks();
	}

	public int remainingTicks()
	{
		return remainingTicks(observedTick);
	}

	public int remainingTicks(int tick)
	{
		return isActive(tick) ? expiryTick - tick : 0;
	}

	public double strength()
	{
		return strength(observedTick);
	}

	public double strength(int tick)
	{
		if (!isActive(tick))
		{
			return 0.0d;
		}

		return remainingTicks(tick) / (double) type.durationTicks();
	}

	private void apply(FreezeType type, int tick, long positionKey)
	{
		this.type = type;
		applicationTick = tick;
		expiryTick = tick + type.durationTicks();
		observedTick = tick;
		this.positionKey = positionKey;
	}

	private static FreezeType typeForGraphic(int graphicId)
	{
		switch (graphicId)
		{
			case SpotanimID.BIND_IMPACT:
				return FreezeType.BIND;
			case SpotanimID.SNARE_IMPACT:
				return FreezeType.SNARE;
			case SpotanimID.ENTANGLE_IMPACT:
				return FreezeType.ENTANGLE;
			case SpotanimID.ICE_RUSH_IMPACT:
				return FreezeType.ICE_RUSH;
			case SpotanimID.ICE_BLITZ_IMPACT:
				return FreezeType.ICE_BURST;
			case SpotanimID.ICE_BURST_IMPACT:
				return FreezeType.ICE_BLITZ;
			case SpotanimID.ICE_BARRAGE_IMPACT:
				return FreezeType.ICE_BARRAGE;
			default:
				return null;
		}
	}
}
